// AUTO-GENERATO da scripts/build-manuale-cards.mjs — non modificare a mano.
// Fonte: public/manuale.html (11 sezioni, verbatim x5 lingue).
import type { Lang } from "@/lib/i18n";

export type ManualeCard = { id: string; index: string; icon: string; image: string | null; tag: Record<Lang, string>; title: Record<Lang, string>; body: Record<Lang, string> };

export const manualeCards: ManualeCard[] = [{"id":"manual-0","index":"001","icon":"KeyRound","image":"assets/manuale-chiavi.jpg","tag":{"it":"Chiavi","en":"Keys","es":"Llaves","fr":"Clés","de":"Schlüssel"},"title":{"it":"Chiavi e telecomando","en":"Keys and remote control","es":"Llaves y mando","fr":"Clés et télécommande","de":"Schlüssel und Fernbedienung"},"body":{"it":"<div class=\"manual-content\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Chiavi e telecomando della casa\" src=\"/assets/manuale-chiavi.jpg\"/>\r\n</div>\r\n<div class=\"note\"><strong>Importante:</strong> durante il soggiorno vi chiediamo di custodire con cura le chiavi e il telecomando. In caso di smarrimento potrebbe essere applicata una penale.</div>\r\n<h3>Telecomando dei cancelli</h3>\r\n<ul class=\"simple-list\">\r\n<li><strong>Tasto A:</strong> apre il cancello della casa, quello che permette di accedere al giardino.</li>\r\n<li><strong>Tasto B:</strong> apre il cancello condominiale.</li>\r\n<li><strong>Tasti C e D:</strong> non hanno nessuna funzionalità per la casa.</li>\r\n</ul>\r\n<h3>Chiave lunga</h3>\r\n<ul class=\"simple-list\">\r\n<li>La <strong>chiave lunga</strong> apre la porta della veranda, cioè la porta d’ingresso della casa.</li>\r\n<li>Per aprire correttamente la porta, inserite la chiave con la parte dritta con lo scalino rivolta verso l’alto.</li>\r\n</ul>\r\n<h3>Altra chiave</h3>\r\n<ul class=\"simple-list\">\r\n<li>L’altra chiave apre il cancelletto vicino al cancello del giardino.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Prima di uscire:</strong> assicuratevi sempre di avere con voi chiavi e telecomando. Prima del check-out, le chiavi dovranno essere lasciate nella cassetta delle lettere come indicato nelle istruzioni di check-out.</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Chiavi e telecomando della casa\" src=\"/assets/manuale-chiavi.jpg\"/>\r\n</div>\r\n<div class=\"note\"><strong>Important:</strong> during your stay, please take good care of the keys and the remote control. In case of loss, a penalty may be applied.</div>\r\n<h3>Gate remote control</h3>\r\n<ul class=\"simple-list\">\r\n<li><strong>Button A:</strong> opens the house gate, the one that gives access to the garden.</li>\r\n<li><strong>Button B:</strong> opens the condominium gate.</li>\r\n<li><strong>Buttons C and D:</strong> they have no function for the house.</li>\r\n</ul>\r\n<h3>Long key</h3>\r\n<ul class=\"simple-list\">\r\n<li>The <strong>long key</strong> opens the veranda door, which is the entrance door to the house.</li>\r\n<li>To open the door correctly, insert the key with the straight stepped side facing upwards.</li>\r\n</ul>\r\n<h3>Other key</h3>\r\n<ul class=\"simple-list\">\r\n<li>The other key opens the small gate next to the garden gate.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Before leaving:</strong> always make sure you have the keys and remote control with you. Before check-out, the keys must be left in the mailbox as explained in the check-out instructions.</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Chiavi e telecomando della casa\" src=\"/assets/manuale-chiavi.jpg\"/>\r\n</div>\r\n<div class=\"note\"><strong>Importante:</strong> durante la estancia, os pedimos que cuidéis bien las llaves y el mando. En caso de pérdida, podría aplicarse una penalización.</div>\r\n<h3>Mando de las puertas</h3>\r\n<ul class=\"simple-list\">\r\n<li><strong>Botón A:</strong> abre la puerta de la casa, la que permite acceder al jardín.</li>\r\n<li><strong>Botón B:</strong> abre la puerta comunitaria.</li>\r\n<li><strong>Botones C y D:</strong> no tienen ninguna función para la casa.</li>\r\n</ul>\r\n<h3>Llave larga</h3>\r\n<ul class=\"simple-list\">\r\n<li>La <strong>llave larga</strong> abre la puerta de la veranda, es decir, la puerta de entrada de la casa.</li>\r\n<li>Para abrir correctamente la puerta, introducid la llave con la parte recta con el escalón hacia arriba.</li>\r\n</ul>\r\n<h3>Otra llave</h3>\r\n<ul class=\"simple-list\">\r\n<li>La otra llave abre la pequeña puerta junto a la puerta del jardín.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Antes de salir:</strong> aseguraos siempre de llevar las llaves y el mando con vosotros. Antes del check-out, las llaves deberán dejarse en el buzón como se indica en las instrucciones de salida.</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Chiavi e telecomando della casa\" src=\"/assets/manuale-chiavi.jpg\"/>\r\n</div>\r\n<div class=\"note\"><strong>Important :</strong> pendant votre séjour, merci de bien garder les clés et la télécommande. En cas de perte, une pénalité peut être appliquée.</div>\r\n<h3>Télécommande des portails</h3>\r\n<ul class=\"simple-list\">\r\n<li><strong>Bouton A :</strong> ouvre le portail de la maison, celui qui permet d’accéder au jardin.</li>\r\n<li><strong>Bouton B :</strong> ouvre le portail de la copropriété.</li>\r\n<li><strong>Boutons C et D :</strong> ils n’ont aucune fonction pour la maison.</li>\r\n</ul>\r\n<h3>Clé longue</h3>\r\n<ul class=\"simple-list\">\r\n<li>La <strong>clé longue</strong> ouvre la porte de la véranda, c’est-à-dire la porte d’entrée de la maison.</li>\r\n<li>Pour ouvrir correctement la porte, insérez la clé avec la partie droite avec l’encoche orientée vers le haut.</li>\r\n</ul>\r\n<h3>Autre clé</h3>\r\n<ul class=\"simple-list\">\r\n<li>L’autre clé ouvre le petit portail à côté du portail du jardin.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Avant de sortir :</strong> assurez-vous toujours d’avoir les clés et la télécommande avec vous. Avant le check-out, les clés devront être laissées dans la boîte aux lettres comme indiqué dans les instructions de départ.</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Chiavi e telecomando della casa\" src=\"/assets/manuale-chiavi.jpg\"/>\r\n</div>\r\n<div class=\"note\"><strong>Wichtig:</strong> während des Aufenthalts bitten wir euch, Schlüssel und Fernbedienung gut aufzubewahren. Im Falle eines Verlusts kann eine Strafe erhoben werden.</div>\r\n<h3>Fernbedienung der Tore</h3>\r\n<ul class=\"simple-list\">\r\n<li><strong>Taste A:</strong> öffnet das Tor des Hauses, das den Zugang zum Garten ermöglicht.</li>\r\n<li><strong>Taste B:</strong> öffnet das Gemeinschaftstor.</li>\r\n<li><strong>Tasten C und D:</strong> haben keine Funktion für das Haus.</li>\r\n</ul>\r\n<h3>Langer Schlüssel</h3>\r\n<ul class=\"simple-list\">\r\n<li>Der <strong>lange Schlüssel</strong> öffnet die Tür der Veranda, also die Eingangstür des Hauses.</li>\r\n<li>Um die Tür richtig zu öffnen, steckt den Schlüssel so ein, dass die gerade Seite mit der Stufe nach oben zeigt.</li>\r\n</ul>\r\n<h3>Anderer Schlüssel</h3>\r\n<ul class=\"simple-list\">\r\n<li>Der andere Schlüssel öffnet das kleine Tor neben dem Gartentor.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Bevor ihr ausgeht:</strong> stellt immer sicher, dass ihr Schlüssel und Fernbedienung bei euch habt. Vor dem Check-out müssen die Schlüssel im Briefkasten hinterlassen werden, wie in den Check-out-Anweisungen angegeben.</div>\r\n</div>\r\n</details>"}},{"id":"wifi","index":"002","icon":"Wifi","image":null,"tag":{"it":"Wi-Fi","en":"Wi-Fi","es":"Wi-Fi","fr":"Wi-Fi","de":"WLAN"},"title":{"it":"Wi-Fi","en":"Wi-Fi","es":"Wi-Fi","fr":"Wi-Fi","de":"Wi-Fi"},"body":{"it":"<div class=\"manual-content\">\r\n<div class=\"info-grid\">\r\n<div class=\"info-card\">\r\n<strong>Nome rete</strong>\r\n<span class=\"placeholder\">A Casa di Marco - Wifi</span>\r\n</div>\r\n<div class=\"info-card\">\r\n<strong>Password</strong>\r\n<span class=\"placeholder\">ACASADIMARCO!17</span>\r\n</div>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li>Se il Wi-Fi non funziona, provate prima a <strong>disattivare e riattivare il Wi-Fi</strong> dal vostro telefono.</li>\r\n<li>Se il problema continua, scriveteci su WhatsApp e vi aiuteremo il prima possibile.</li>\r\n</ul>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<div class=\"info-grid\">\r\n<div class=\"info-card\">\r\n<strong>Network name</strong>\r\n<span class=\"placeholder\">A Casa di Marco - Wifi</span>\r\n</div>\r\n<div class=\"info-card\">\r\n<strong>Password</strong>\r\n<span class=\"placeholder\">ACASADIMARCO!17</span>\r\n</div>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li>If the Wi-Fi does not work, first try <strong>turning Wi-Fi off and on again</strong> on your phone.</li>\r\n<li>If the problem continues, message us on WhatsApp and we will help you as soon as possible.</li>\r\n</ul>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<div class=\"info-grid\">\r\n<div class=\"info-card\">\r\n<strong>Nombre de la red</strong>\r\n<span class=\"placeholder\">A Casa di Marco - Wifi</span>\r\n</div>\r\n<div class=\"info-card\">\r\n<strong>Contraseña</strong>\r\n<span class=\"placeholder\">ACASADIMARCO!17</span>\r\n</div>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li>Si el Wi-Fi no funciona, probad primero a <strong>desactivar y volver a activar el Wi-Fi</strong> en vuestro teléfono.</li>\r\n<li>Si el problema continúa, escribidnos por WhatsApp y os ayudaremos lo antes posible.</li>\r\n</ul>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<div class=\"info-grid\">\r\n<div class=\"info-card\">\r\n<strong>Nom du réseau</strong>\r\n<span class=\"placeholder\">A Casa di Marco - Wifi</span>\r\n</div>\r\n<div class=\"info-card\">\r\n<strong>Mot de passe</strong>\r\n<span class=\"placeholder\">ACASADIMARCO!17</span>\r\n</div>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li>Si le Wi-Fi ne fonctionne pas, essayez d'abord de <strong>désactiver puis réactiver le Wi-Fi</strong> sur votre téléphone.</li>\r\n<li>Si le problème continue, écrivez-nous sur WhatsApp et nous vous aiderons dès que possible.</li>\r\n</ul>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<div class=\"info-grid\">\r\n<div class=\"info-card\">\r\n<strong>Netzwerkname</strong>\r\n<span class=\"placeholder\">A Casa di Marco - Wifi</span>\r\n</div>\r\n<div class=\"info-card\">\r\n<strong>Passwort</strong>\r\n<span class=\"placeholder\">ACASADIMARCO!17</span>\r\n</div>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li>Wenn das Wi-Fi nicht funktioniert, versucht zuerst, das <strong>Wi-Fi aus- und wieder einzuschalten</strong> auf eurem Telefon.</li>\r\n<li>Wenn das Problem weiterhin besteht, schreibt uns auf WhatsApp und wir helfen euch so schnell wie möglich.</li>\r\n</ul>\r\n</div>\r\n</details>"}},{"id":"rifiuti","index":"003","icon":"Recycle","image":null,"tag":{"it":"Differenziata","en":"Waste sorting","es":"Recogida selectiva","fr":"Tri sélectif","de":"Mülltrennung"},"title":{"it":"Raccolta differenziata","en":"Waste sorting","es":"Recogida selectiva","fr":"Tri des déchets","de":"Mülltrennung"},"body":{"it":"<div class=\"manual-content\">\r\n<div class=\"note\"><strong>Importante:</strong> i bidoncini presenti in giardino non devono essere portati dentro casa. Durante il soggiorno potete usarli per raccogliere i rifiuti, rispettando la raccolta differenziata. Alla fine del soggiorno vi chiediamo gentilmente di raccogliere tutta la spazzatura e di buttarla negli appositi bidoni condominiali, che si trovano accanto al cancello condominiale.</div>\r\n<table class=\"waste-table\">\r\n<thead>\r\n<tr>\r\n<th>Categoria</th>\r\n<th>Cosa mettere</th>\r\n<th>Attenzione</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Organico</td>\r\n<td>Scarti di cucina, avanzi di cibo, gusci d’uovo, fondi di caffè e tè, tovaglioli di carta sporchi di cibo.</td>\r\n<td>Usare sacchetti compostabili. Non usare sacchi di plastica.</td>\r\n</tr>\r\n<tr>\r\n<td>Plastica, acciaio e alluminio</td>\r\n<td>Bottiglie di plastica, vasetti yogurt, flaconi, buste per alimenti, vaschette, lattine, bombolette spray vuote, barattoli, tappi e coperchi.</td>\r\n<td>Non mettere giocattoli, CD/DVD, oggetti in gomma, cavi, tubi, posate di plastica o sacchetti in bioplastica.</td>\r\n</tr>\r\n<tr>\r\n<td>Carta e cartone</td>\r\n<td>Giornali, riviste, fogli, scatole, imballaggi in cartone, sacchetti di carta, confezioni in cartoncino pulite.</td>\r\n<td>Non mettere scontrini, carta oleata, carta da forno, fazzoletti usati o cartoni sporchi di cibo.</td>\r\n</tr>\r\n<tr>\r\n<td>Vetro</td>\r\n<td>Bottiglie, vasetti e contenitori in vetro vuoti, senza tappi.</td>\r\n<td>Non mettere bicchieri, specchi, ceramica, porcellana, lampadine, pyrex o vetri di finestre.</td>\r\n</tr>\r\n<tr>\r\n<td>Indifferenziato</td>\r\n<td>Pannolini, assorbenti, calze di nylon, rasoi, spazzole, carta plastificata, carta da forno, cerotti, gomme da masticare, scontrini.</td>\r\n<td>Non mettere carta, vetro, plastica, organico, pile, farmaci, olio o piccoli elettrodomestici.</td>\r\n</tr>\r\n<tr>\r\n<td>Farmaci, pile e olio</td>\r\n<td>Farmaci scaduti, pile, batterie e olio vegetale usato non vanno buttati nei normali bidoni.</td>\r\n<td>Vanno conferiti negli appositi contenitori, farmacie, esercizi autorizzati o centri di raccolta.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"do-dont\">\r\n<div class=\"do-box\">\r\n<strong>Da fare</strong>\r\n<p>A fine soggiorno vi chiediamo gentilmente di raccogliere tutta la spazzatura e di buttarla negli appositi bidoni condominiali, che si trovano accanto al cancello condominiale.</p>\r\n</div>\r\n<div class=\"dont-box\">\r\n<strong>Da evitare</strong>\r\n<p>Non lasciate l'organico sotto al lavandino per troppo tempo e non usate sacchi neri.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<div class=\"note\"><strong>Important:</strong> the small bins in the garden must not be brought inside the house. During your stay, you can use them to collect rubbish, while respecting waste sorting rules. At the end of your stay, please collect all rubbish and throw it into the proper condominium bins located next to the condominium gate.</div>\r\n<table class=\"waste-table\">\r\n<thead>\r\n<tr>\r\n<th>Category</th>\r\n<th>What to put</th>\r\n<th>Pay attention</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Organic waste</td>\r\n<td>Kitchen scraps, food leftovers, eggshells, coffee grounds, tea bags and paper napkins dirty with food.</td>\r\n<td>Use compostable bags. Do not use plastic bags.</td>\r\n</tr>\r\n<tr>\r\n<td>Plastic, steel and aluminium</td>\r\n<td>Plastic bottles, yogurt pots, bottles for detergents, food bags, trays, cans, empty spray cans, tins, caps and lids.</td>\r\n<td>Do not put toys, CDs/DVDs, rubber objects, cables, pipes, plastic cutlery or bioplastic bags.</td>\r\n</tr>\r\n<tr>\r\n<td>Paper and cardboard</td>\r\n<td>Newspapers, magazines, sheets of paper, boxes, cardboard packaging, paper bags and clean cardboard packaging.</td>\r\n<td>Do not put receipts, waxed paper, baking paper, used tissues or cardboard dirty with food.</td>\r\n</tr>\r\n<tr>\r\n<td>Glass</td>\r\n<td>Empty glass bottles, jars and containers, without caps.</td>\r\n<td>Do not put drinking glasses, mirrors, ceramics, porcelain, light bulbs, pyrex or window glass.</td>\r\n</tr>\r\n<tr>\r\n<td>Non-recyclable waste</td>\r\n<td>Nappies, sanitary pads, nylon tights, razors, brushes, plastic-coated paper, baking paper, plasters, chewing gum, receipts.</td>\r\n<td>Do not put paper, glass, plastic, organic waste, batteries, medicines, oil or small electronic devices.</td>\r\n</tr>\r\n<tr>\r\n<td>Medicines, batteries and oil</td>\r\n<td>Expired medicines, batteries and used vegetable oil must not be thrown into normal bins.</td>\r\n<td>They must be taken to dedicated containers, pharmacies, authorised shops or collection centres.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"do-dont\">\r\n<div class=\"do-box\">\r\n<strong>Please do</strong>\r\n<p>At the end of your stay, please collect all rubbish and throw it into the proper condominium bins located next to the condominium gate.</p>\r\n</div>\r\n<div class=\"dont-box\">\r\n<strong>Please avoid</strong>\r\n<p>Do not leave organic waste under the sink for too long and do not use black bags.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<div class=\"note\"><strong>Importante:</strong> los cubos pequeños del jardín no deben llevarse dentro de la casa. Durante la estancia podéis usarlos para recoger la basura, respetando la recogida selectiva. Al final de la estancia, os pedimos amablemente que recojáis toda la basura y la tiréis en los contenedores correspondientes del edificio, situados junto a la puerta comunitaria.</div>\r\n<table class=\"waste-table\">\r\n<thead>\r\n<tr>\r\n<th>Categoría</th>\r\n<th>Qué poner</th>\r\n<th>Atención</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Orgánico</td>\r\n<td>Restos de cocina, sobras de comida, cáscaras de huevo, posos de café y té, servilletas de papel sucias de comida.</td>\r\n<td>Usar bolsas compostables. No usar bolsas de plástico.</td>\r\n</tr>\r\n<tr>\r\n<td>Plástico, acero y aluminio</td>\r\n<td>Botellas de plástico, envases de yogur, botes, bolsas para alimentos, bandejas, latas, aerosoles vacíos, tarros, tapones y tapas.</td>\r\n<td>No tirar juguetes, CD/DVD, objetos de goma, cables, tubos, cubiertos de plástico o bolsas de bioplástico.</td>\r\n</tr>\r\n<tr>\r\n<td>Papel y cartón</td>\r\n<td>Periódicos, revistas, hojas, cajas, embalajes de cartón, bolsas de papel y envases de cartoncillo limpios.</td>\r\n<td>No tirar recibos, papel encerado, papel de horno, pañuelos usados o cartones sucios de comida.</td>\r\n</tr>\r\n<tr>\r\n<td>Vidrio</td>\r\n<td>Botellas, tarros y envases de vidrio vacíos, sin tapas.</td>\r\n<td>No tirar vasos, espejos, cerámica, porcelana, bombillas, pyrex o cristales de ventanas.</td>\r\n</tr>\r\n<tr>\r\n<td>No reciclable</td>\r\n<td>Pañales, compresas, medias de nylon, cuchillas, cepillos, papel plastificado, papel de horno, tiritas, chicles, recibos.</td>\r\n<td>No tirar papel, vidrio, plástico, orgánico, pilas, medicamentos, aceite o pequeños electrodomésticos.</td>\r\n</tr>\r\n<tr>\r\n<td>Medicamentos, pilas y aceite</td>\r\n<td>Los medicamentos caducados, pilas, baterías y aceite vegetal usado no deben tirarse en los contenedores normales.</td>\r\n<td>Deben depositarse en contenedores específicos, farmacias, tiendas autorizadas o centros de recogida.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"do-dont\">\r\n<div class=\"do-box\">\r\n<strong>Qué hacer</strong>\r\n<p>Al final de la estancia, os pedimos amablemente que recojáis toda la basura y la tiréis en los contenedores correspondientes del edificio, situados junto a la puerta comunitaria.</p>\r\n</div>\r\n<div class=\"dont-box\">\r\n<strong>Qué evitar</strong>\r\n<p>No dejéis el orgánico debajo del fregadero durante demasiado tiempo y no uséis bolsas negras.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<div class=\"note\"><strong>Important :</strong> les petites poubelles du jardin ne doivent pas être apportées à l’intérieur de la maison. Pendant votre séjour, vous pouvez les utiliser pour collecter les déchets, en respectant le tri sélectif. À la fin du séjour, merci de rassembler tous les déchets et de les jeter dans les poubelles de la copropriété prévues à cet effet, situées à côté du portail de la copropriété.</div>\r\n<table class=\"waste-table\">\r\n<thead>\r\n<tr>\r\n<th>Catégorie</th>\r\n<th>Quoi jeter</th>\r\n<th>Attention</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Déchets organiques</td>\r\n<td>Déchets de cuisine, restes alimentaires, coquilles d'œufs, marc de café, thé et serviettes en papier sales de nourriture.</td>\r\n<td>Utiliser des sacs compostables. Ne pas utiliser de sacs en plastique.</td>\r\n</tr>\r\n<tr>\r\n<td>Plastique, acier et aluminium</td>\r\n<td>Bouteilles en plastique, pots de yaourt, flacons, sacs alimentaires, barquettes, canettes, aérosols vides, boîtes, bouchons et couvercles.</td>\r\n<td>Ne pas jeter de jouets, CD/DVD, objets en caoutchouc, câbles, tuyaux, couverts en plastique ou sacs en bioplastique.</td>\r\n</tr>\r\n<tr>\r\n<td>Papier et carton</td>\r\n<td>Journaux, magazines, feuilles, boîtes, emballages en carton, sacs en papier et emballages en carton propres.</td>\r\n<td>Ne pas jeter les tickets de caisse, le papier ciré, le papier cuisson, les mouchoirs usagés ou les cartons sales de nourriture.</td>\r\n</tr>\r\n<tr>\r\n<td>Verre</td>\r\n<td>Bouteilles, bocaux et contenants en verre vides, sans bouchons.</td>\r\n<td>Ne pas jeter les verres à boire, miroirs, céramique, porcelaine, ampoules, pyrex ou vitres.</td>\r\n</tr>\r\n<tr>\r\n<td>Déchets non recyclables</td>\r\n<td>Couches, protections hygiéniques, collants en nylon, rasoirs, brosses, papier plastifié, papier cuisson, pansements, chewing-gums, tickets de caisse.</td>\r\n<td>Ne pas jeter le papier, le verre, le plastique, les déchets organiques, piles, médicaments, huile ou petits appareils électroniques.</td>\r\n</tr>\r\n<tr>\r\n<td>Médicaments, piles et huile</td>\r\n<td>Les médicaments périmés, piles, batteries et huile végétale usagée ne doivent pas être jetés dans les poubelles normales.</td>\r\n<td>Ils doivent être déposés dans les conteneurs dédiés, pharmacies, magasins autorisés ou centres de collecte.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"do-dont\">\r\n<div class=\"do-box\">\r\n<strong>À faire</strong>\r\n<p>À la fin du séjour, merci de rassembler tous les déchets et de les jeter dans les poubelles de la copropriété prévues à cet effet, situées à côté du portail de la copropriété.</p>\r\n</div>\r\n<div class=\"dont-box\">\r\n<strong>À éviter</strong>\r\n<p>Ne laissez pas les déchets organiques sous l'évier trop longtemps et n'utilisez pas de sacs noirs.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<div class=\"note\"><strong>Wichtig:</strong> die kleinen Mülltonnen im Garten dürfen nicht ins Haus gebracht werden. Während des Aufenthalts könnt ihr sie nutzen, um den Müll zu sammeln, und dabei die Mülltrennung beachten. Am Ende des Aufenthalts bitten wir euch freundlich, den gesamten Müll einzusammeln und in die dafür vorgesehenen Gemeinschaftsmülltonnen zu werfen, die sich neben dem Gemeinschaftstor befinden.</div>\r\n<table class=\"waste-table\">\r\n<thead>\r\n<tr>\r\n<th>Kategorie</th>\r\n<th>Was hineingehört</th>\r\n<th>Achtung</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Organischer Abfall</td>\r\n<td>Küchenabfälle, Essensreste, Eierschalen, Kaffeesatz und Tee, Papierservietten, die mit Essen verschmutzt sind.</td>\r\n<td>Kompostierbare Beutel verwenden. Keine Plastiksäcke verwenden.</td>\r\n</tr>\r\n<tr>\r\n<td>Plastik, Stahl und Aluminium</td>\r\n<td>Plastikflaschen, Joghurtbecher, Flaschen, Lebensmittelbeutel, Schalen, Dosen, leere Spraydosen, Konservendosen, Verschlüsse und Deckel.</td>\r\n<td>Keine Spielzeuge, CDs/DVDs, Gummigegenstände, Kabel, Schläuche, Plastikbesteck oder Bioplastikbeutel hineinwerfen.</td>\r\n</tr>\r\n<tr>\r\n<td>Papier und Pappe</td>\r\n<td>Zeitungen, Zeitschriften, Blätter, Kartons, Pappverpackungen, Papiertüten und saubere Kartonverpackungen.</td>\r\n<td>Keine Kassenbons, Wachspapier, Backpapier, gebrauchte Taschentücher oder mit Essen verschmutzte Kartons hineinwerfen.</td>\r\n</tr>\r\n<tr>\r\n<td>Glas</td>\r\n<td>Leere Glasflaschen, Gläser und Glasbehälter ohne Verschlüsse.</td>\r\n<td>Keine Trinkgläser, Spiegel, Keramik, Porzellan, Glühbirnen, Pyrex oder Fensterglas hineinwerfen.</td>\r\n</tr>\r\n<tr>\r\n<td>Restmüll</td>\r\n<td>Windeln, Binden, Nylonstrumpfhosen, Rasierer, Bürsten, beschichtetes Papier, Backpapier, Pflaster, Kaugummis, Kassenbons.</td>\r\n<td>Kein Papier, Glas, Plastik, keinen Bioabfall, keine Batterien, Medikamente, kein Öl und keine kleinen Elektrogeräte hineinwerfen.</td>\r\n</tr>\r\n<tr>\r\n<td>Medikamente, Batterien und Öl</td>\r\n<td>Abgelaufene Medikamente, Batterien und gebrauchtes Pflanzenöl dürfen nicht in die normalen Mülltonnen geworfen werden.</td>\r\n<td>Sie müssen in die dafür vorgesehenen Behälter, Apotheken, autorisierte Geschäfte oder Sammelstellen gebracht werden.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"do-dont\">\r\n<div class=\"do-box\">\r\n<strong>Bitte tun</strong>\r\n<p>Am Ende des Aufenthalts bitten wir euch freundlich, den gesamten Müll einzusammeln und in die dafür vorgesehenen Gemeinschaftsmülltonnen zu werfen, die sich neben dem Gemeinschaftstor befinden.</p>\r\n</div>\r\n<div class=\"dont-box\">\r\n<strong>Bitte vermeiden</strong>\r\n<p>Lasst den Bioabfall nicht zu lange unter der Spüle liegen und verwendet keine schwarzen Müllsäcke.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>"}},{"id":"clima","index":"004","icon":"Thermometer","image":"assets/manuale-termostato.jpg","tag":{"it":"Clima","en":"Climate","es":"Clima","fr":"Climat","de":"Klima"},"title":{"it":"Clima e riscaldamento","en":"Air conditioning and heating","es":"Clima y calefacción","fr":"Climatisation et chauffage","de":"Klimaanlage und Heizung"},"body":{"it":"<div class=\"manual-content\">\r\n<h3>Termostato dei termosifoni</h3>\r\n<div class=\"thermostat-visual\">\r\n<img alt=\"Termostato dei termosifoni\" src=\"/assets/manuale-termostato.jpg\"/>\r\n</div>\r\n<ol class=\"step-list\">\r\n<li>Per accendere il riscaldamento, premete il tasto <strong>ON</strong>.</li>\r\n<li>Girate la manopola fino alla temperatura desiderata.</li>\r\n<li>Aspettate circa <strong>1 ora</strong> affinché la casa raggiunga la temperatura impostata.</li>\r\n<li>Quando la casa è calda, potete spegnere il termostato: premete <strong>OFF</strong> e girate la manopola su <strong>0</strong>.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Importante:</strong> per spegnere davvero i termosifoni bisogna fare entrambe le cose: premere <strong>OFF</strong> e girare la manopola su <strong>0</strong>. Se non girate la manopola, i termosifoni potrebbero continuare a funzionare.</div>\r\n<h3>Telecomando del condizionatore</h3>\r\n<div class=\"remote-top-layout\">\r\n<div class=\"remote-image-box\">\r\n<img alt=\"Telecomando del condizionatore con tasti evidenziati\" src=\"/assets/manuale-condizionatore-telecomando.jpg\"/>\r\n</div>\r\n<div class=\"remote-highlight-list\">\r\n<div class=\"remote-card remote-red\">\r\n<strong>Tasto ON/OFF</strong>\r\n<p>Serve per accendere e spegnere il condizionatore.</p>\r\n</div>\r\n<div class=\"remote-card remote-blue\">\r\n<strong>Tasto MODE</strong>\r\n<p>Serve per scegliere la modalità del condizionatore. Premendolo più volte potete cambiare tra freddo, caldo, deumidificazione, ventilazione e automatico.</p>\r\n</div>\r\n<div class=\"remote-card remote-yellow\">\r\n<strong>Tasti TEMP</strong>\r\n<p>Servono per aumentare o diminuire la temperatura. La freccia verso l’alto aumenta i gradi, la freccia verso il basso li diminuisce.</p>\r\n</div>\r\n<div class=\"remote-card remote-purple\">\r\n<strong>Tasto FAN SPEED</strong>\r\n<p>Serve per regolare la velocità dell’aria. Se non sapete cosa scegliere, lasciate una velocità media oppure automatica.</p>\r\n</div>\r\n<div class=\"remote-card remote-cyan\">\r\n<strong>Tasto SLEEP</strong>\r\n<p>Serve per la modalità notte. Riduce il funzionamento del condizionatore durante il riposo.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"remote-warning\"><strong>Importante:</strong> ogni volta che usate il telecomando, puntatelo verso il condizionatore. Se non è rivolto verso il condizionatore, il comando potrebbe non funzionare.</div>\r\n<div class=\"remote-warning\"><strong>È vietato lasciare il condizionatore acceso quando non siete in casa.</strong> Prima di uscire, controllate sempre di averlo spento.</div>\r\n<div class=\"remote-subtitle\">Altri tasti utili</div>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasti SWING</strong>\r\n<p>Servono per orientare il flusso d’aria, verso l’alto, il basso o lateralmente.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto SUPER</strong>\r\n<p>Serve per raffreddare o riscaldare più velocemente. Usatelo solo per poco tempo.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto QUIET</strong>\r\n<p>Serve per rendere il condizionatore più silenzioso.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto SMART</strong>\r\n<p>Serve per una gestione automatica della temperatura.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasti ON TIMER / OFF TIMER</strong>\r\n<p>Servono per programmare l’accensione o lo spegnimento automatico.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<h3>Radiator thermostat</h3>\r\n<div class=\"thermostat-visual\">\r\n<img alt=\"Termostato dei termosifoni\" src=\"/assets/manuale-termostato.jpg\"/>\r\n</div>\r\n<ol class=\"step-list\">\r\n<li>To turn on the heating, press the <strong>ON</strong> button.</li>\r\n<li>Turn the dial to the desired temperature.</li>\r\n<li>Wait about <strong>1 hour</strong> for the house to reach the set temperature.</li>\r\n<li>When the house is warm, you can turn the thermostat off: press <strong>OFF</strong> and turn the dial to <strong>0</strong>.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Important:</strong> to properly turn off the radiators, you must do both: press <strong>OFF</strong> and turn the dial to <strong>0</strong>. If you do not turn the dial, the radiators may keep working.</div>\r\n<h3>Air conditioner remote control</h3>\r\n<div class=\"remote-top-layout\">\r\n<div class=\"remote-image-box\">\r\n<img alt=\"Telecomando del condizionatore con tasti evidenziati\" src=\"/assets/manuale-condizionatore-telecomando.jpg\"/>\r\n</div>\r\n<div class=\"remote-highlight-list\">\r\n<div class=\"remote-card remote-red\">\r\n<strong>ON/OFF button</strong>\r\n<p>Use this button to turn the air conditioner on and off.</p>\r\n</div>\r\n<div class=\"remote-card remote-blue\">\r\n<strong>MODE button</strong>\r\n<p>Use this button to choose the air conditioner mode. Press it several times to switch between cooling, heating, dry, fan and automatic mode.</p>\r\n</div>\r\n<div class=\"remote-card remote-yellow\">\r\n<strong>TEMP buttons</strong>\r\n<p>Use these buttons to increase or decrease the temperature. The up arrow increases the degrees, the down arrow decreases them.</p>\r\n</div>\r\n<div class=\"remote-card remote-purple\">\r\n<strong>FAN SPEED button</strong>\r\n<p>Use this button to adjust the fan speed. If you are not sure, leave it on medium or automatic speed.</p>\r\n</div>\r\n<div class=\"remote-card remote-cyan\">\r\n<strong>SLEEP button</strong>\r\n<p>Use this for night mode. It reduces the air conditioner operation during rest.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"remote-warning\"><strong>Important:</strong> every time you use the remote control, point it towards the air conditioner. If it is not facing the unit, the command may not work.</div>\r\n<div class=\"remote-warning\"><strong>It is forbidden to leave the air conditioner on when you are not at home.</strong> Before going out, always check that it is turned off.</div>\r\n<div class=\"remote-subtitle\">Other useful buttons</div>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>SWING buttons</strong>\r\n<p>Use these buttons to direct the airflow upward, downward or sideways.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>SUPER button</strong>\r\n<p>Use this button to cool or heat faster. Use it only for a short time.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>QUIET button</strong>\r\n<p>Use this button to make the air conditioner quieter.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>SMART button</strong>\r\n<p>Use this button for automatic temperature management.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>ON TIMER / OFF TIMER buttons</strong>\r\n<p>Use these buttons to schedule automatic switch-on or switch-off.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<h3>Termostato de los radiadores</h3>\r\n<div class=\"thermostat-visual\">\r\n<img alt=\"Termostato dei termosifoni\" src=\"/assets/manuale-termostato.jpg\"/>\r\n</div>\r\n<ol class=\"step-list\">\r\n<li>Para encender la calefacción, pulsad el botón <strong>ON</strong>.</li>\r\n<li>Girad la rueda hasta la temperatura deseada.</li>\r\n<li>Esperad aproximadamente <strong>1 hora</strong> para que la casa alcance la temperatura establecida.</li>\r\n<li>Cuando la casa esté caliente, podéis apagar el termostato: pulsad <strong>OFF</strong> y girad la rueda a <strong>0</strong>.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Importante:</strong> para apagar correctamente los radiadores hay que hacer ambas cosas: pulsar <strong>OFF</strong> y girar la rueda a <strong>0</strong>. Si no giráis la rueda, los radiadores podrían seguir funcionando.</div>\r\n<h3>Mando del aire acondicionado</h3>\r\n<div class=\"remote-top-layout\">\r\n<div class=\"remote-image-box\">\r\n<img alt=\"Telecomando del condizionatore con tasti evidenziati\" src=\"/assets/manuale-condizionatore-telecomando.jpg\"/>\r\n</div>\r\n<div class=\"remote-highlight-list\">\r\n<div class=\"remote-card remote-red\">\r\n<strong>Botón ON/OFF</strong>\r\n<p>Sirve para encender y apagar el aire acondicionado.</p>\r\n</div>\r\n<div class=\"remote-card remote-blue\">\r\n<strong>Botón MODE</strong>\r\n<p>Sirve para elegir el modo del aire acondicionado. Pulsándolo varias veces podéis cambiar entre frío, calor, deshumidificación, ventilación y automático.</p>\r\n</div>\r\n<div class=\"remote-card remote-yellow\">\r\n<strong>Botones TEMP</strong>\r\n<p>Sirven para subir o bajar la temperatura. La flecha hacia arriba aumenta los grados, la flecha hacia abajo los disminuye.</p>\r\n</div>\r\n<div class=\"remote-card remote-purple\">\r\n<strong>Botón FAN SPEED</strong>\r\n<p>Sirve para regular la velocidad del aire. Si no sabéis qué elegir, dejad una velocidad media o automática.</p>\r\n</div>\r\n<div class=\"remote-card remote-cyan\">\r\n<strong>Botón SLEEP</strong>\r\n<p>Sirve para el modo noche. Reduce el funcionamiento del aire acondicionado durante el descanso.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"remote-warning\"><strong>Importante:</strong> cada vez que uséis el mando, apuntadlo hacia el aire acondicionado. Si no está orientado hacia el aparato, el comando podría no funzionare.</div>\r\n<div class=\"remote-warning\"><strong>Está prohibido dejar el aire acondicionado encendido cuando non estáis en casa.</strong> Antes de salir, comprobad siempre que esté apagado.</div>\r\n<div class=\"remote-subtitle\">Otros botones útiles</div>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botones SWING</strong>\r\n<p>Sirven para orientar el flujo de aire, hacia arriba, abajo o lateralmente.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón SUPER</strong>\r\n<p>Sirve para enfriar o calentar más rápido. Usadlo solo durante poco tiempo.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón QUIET</strong>\r\n<p>Sirve para hacer que el aire acondicionado sea más silencioso.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón SMART</strong>\r\n<p>Sirve para una gestión automática de la temperatura.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botones ON TIMER / OFF TIMER</strong>\r\n<p>Sirven para programar el encendido o apagado automático.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<h3>Thermostat des radiateurs</h3>\r\n<div class=\"thermostat-visual\">\r\n<img alt=\"Termostato dei termosifoni\" src=\"/assets/manuale-termostato.jpg\"/>\r\n</div>\r\n<ol class=\"step-list\">\r\n<li>Pour allumer le chauffage, appuyez sur le bouton <strong>ON</strong>.</li>\r\n<li>Tournez la molette jusqu’à la température souhaitée.</li>\r\n<li>Attendez environ <strong>1 heure</strong> pour que la maison atteigne la température réglée.</li>\r\n<li>Quand la maison est chaude, vous pouvez éteindre le thermostat : appuyez sur <strong>OFF</strong> et tournez la molette sur <strong>0</strong>.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Important :</strong> pour éteindre correctement les radiateurs, il faut faire les deux choses : appuyer sur <strong>OFF</strong> et tourner la molette sur <strong>0</strong>. Si vous ne tournez pas la molette, les radiateurs peuvent continuer à fonctionner.</div>\r\n<h3>Télécommande de la climatisation</h3>\r\n<div class=\"remote-top-layout\">\r\n<div class=\"remote-image-box\">\r\n<img alt=\"Telecomando del condizionatore con tasti evidenziati\" src=\"/assets/manuale-condizionatore-telecomando.jpg\"/>\r\n</div>\r\n<div class=\"remote-highlight-list\">\r\n<div class=\"remote-card remote-red\">\r\n<strong>Bouton ON/OFF</strong>\r\n<p>Il sert à allumer et éteindre la climatisation.</p>\r\n</div>\r\n<div class=\"remote-card remote-blue\">\r\n<strong>Bouton MODE</strong>\r\n<p>Il sert à choisir le mode de la climatisation. Appuyez plusieurs fois pour passer entre froid, chaud, déshumidification, ventilation et automatique.</p>\r\n</div>\r\n<div class=\"remote-card remote-yellow\">\r\n<strong>Boutons TEMP</strong>\r\n<p>Ils servent à augmenter ou diminuer la température. La flèche vers le haut augmente les degrés, la flèche vers le bas les diminue.</p>\r\n</div>\r\n<div class=\"remote-card remote-purple\">\r\n<strong>Bouton FAN SPEED</strong>\r\n<p>Il sert à régler la vitesse de l’air. Si vous ne savez pas quoi choisir, laissez une vitesse moyenne ou automatique.</p>\r\n</div>\r\n<div class=\"remote-card remote-cyan\">\r\n<strong>Bouton SLEEP</strong>\r\n<p>Il sert au mode nuit. Il réduit le fonctionnement de la climatisation pendant le repos.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"remote-warning\"><strong>Important :</strong> chaque fois que vous utilisez la télécommande, dirigez-la vers la climatisation. Si elle n’est pas orientée vers l’appareil, la commande peut ne pas fonctionner.</div>\r\n<div class=\"remote-warning\"><strong>Il est interdit de laisser la climatisation allumée lorsque vous n’êtes pas dans la maison.</strong> Avant de sortir, vérifiez toujours qu’elle est éteinte.</div>\r\n<div class=\"remote-subtitle\">Autres boutons utiles</div>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>Boutons SWING</strong>\r\n<p>Ils servent à orienter le flux d’air vers le haut, le bas ou latéralement.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton SUPER</strong>\r\n<p>Il sert à refroidir ou chauffer plus rapidement. Utilisez-le seulement peu de temps.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton QUIET</strong>\r\n<p>Il sert à rendre la climatisation plus silencieuse.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton SMART</strong>\r\n<p>Il sert à une gestion automatique de la température.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Boutons ON TIMER / OFF TIMER</strong>\r\n<p>Ils servent à programmer l’allumage ou l’arrêt automatique.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<h3>Thermostat der Heizkörper</h3>\r\n<div class=\"thermostat-visual\">\r\n<img alt=\"Termostato dei termosifoni\" src=\"/assets/manuale-termostato.jpg\"/>\r\n</div>\r\n<ol class=\"step-list\">\r\n<li>Um die Heizung einzuschalten, drückt die <strong>ON</strong>-Taste.</li>\r\n<li>Dreht den Regler bis zur gewünschten Temperatur.</li>\r\n<li>Wartet etwa <strong>1 Stunde</strong>, bis das Haus die eingestellte Temperatur erreicht hat.</li>\r\n<li>Wenn das Haus warm ist, könnt ihr den Thermostat ausschalten: drückt <strong>OFF</strong> und dreht den Regler auf <strong>0</strong>.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Wichtig:</strong> um die Heizkörper wirklich auszuschalten, müsst ihr beides tun: <strong>OFF</strong> drücken und den Regler auf <strong>0</strong> drehen. Wenn ihr den Regler nicht dreht, können die Heizkörper weiter funktionieren.</div>\r\n<h3>Fernbedienung der Klimaanlage</h3>\r\n<div class=\"remote-top-layout\">\r\n<div class=\"remote-image-box\">\r\n<img alt=\"Telecomando del condizionatore con tasti evidenziati\" src=\"/assets/manuale-condizionatore-telecomando.jpg\"/>\r\n</div>\r\n<div class=\"remote-highlight-list\">\r\n<div class=\"remote-card remote-red\">\r\n<strong>ON/OFF-Taste</strong>\r\n<p>Sie dient zum Ein- und Ausschalten der Klimaanlage.</p>\r\n</div>\r\n<div class=\"remote-card remote-blue\">\r\n<strong>MODE-Taste</strong>\r\n<p>Sie dient zur Auswahl des Modus der Klimaanlage. Durch mehrmaliges Drücken könnt ihr zwischen Kühlen, Heizen, Entfeuchten, Lüften und Automatik wechseln.</p>\r\n</div>\r\n<div class=\"remote-card remote-yellow\">\r\n<strong>TEMP-Tasten</strong>\r\n<p>Sie dienen zum Erhöhen oder Verringern der Temperatur. Der Pfeil nach oben erhöht die Grade, der Pfeil nach unten verringert sie.</p>\r\n</div>\r\n<div class=\"remote-card remote-purple\">\r\n<strong>FAN SPEED-Taste</strong>\r\n<p>Sie dient zum Einstellen der Luftgeschwindigkeit. Wenn ihr nicht wisst, was ihr wählen sollt, lasst eine mittlere oder automatische Geschwindigkeit eingestellt.</p>\r\n</div>\r\n<div class=\"remote-card remote-cyan\">\r\n<strong>SLEEP-Taste</strong>\r\n<p>Sie dient für den Nachtmodus. Sie reduziert den Betrieb der Klimaanlage während der Ruhezeit.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"remote-warning\"><strong>Wichtig:</strong> jedes Mal, wenn ihr die Fernbedienung benutzt, richtet sie auf die Klimaanlage. Wenn sie nicht auf die Klimaanlage gerichtet ist, könnte der Befehl nicht funktionieren.</div>\r\n<div class=\"remote-warning\"><strong>Es ist verboten, die Klimaanlage eingeschaltet zu lassen, wenn ihr nicht im Haus seid.</strong> Bevor ihr ausgeht, prüft immer, dass sie ausgeschaltet ist.</div>\r\n<div class=\"remote-subtitle\">Weitere nützliche Tasten</div>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>SWING-Tasten</strong>\r\n<p>Sie dienen zum Ausrichten des Luftstroms nach oben, unten oder zur Seite.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>SUPER-Taste</strong>\r\n<p>Sie dient zum schnelleren Kühlen oder Heizen. Benutzt sie nur für kurze Zeit.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>QUIET-Taste</strong>\r\n<p>Sie dient dazu, die Klimaanlage leiser zu machen.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>SMART-Taste</strong>\r\n<p>Sie dient zur automatischen Temperaturregelung.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>ON TIMER / OFF TIMER-Tasten</strong>\r\n<p>Sie dienen zum Programmieren des automatischen Ein- oder Ausschaltens.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</details>"}},{"id":"manual-4","index":"005","icon":"Umbrella","image":"assets/manuale-ombrellone.png","tag":{"it":"Ombrellone","en":"Umbrella","es":"Sombrilla","fr":"Parasol","de":"Sonnenschirm"},"title":{"it":"Ombrellone da giardino","en":"Garden umbrella","es":"Sombrilla de jardín","fr":"Parasol de jardin","de":"Gartenschirm"},"body":{"it":"<div class=\"manual-content\">\r\n<div class=\"warning-box\"><strong>Importante:</strong> prima di aprire l’ombrellone, assicuratevi che intorno ci sia spazio libero e che i bracci non tocchino piante, muri, sedie o altri oggetti. Non forzate mai maniglia, manovella o pedale.</div>\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Guida visiva per aprire e chiudere l’ombrellone da giardino\" src=\"/assets/manuale-ombrellone.png\"/>\r\n</div>\r\n<h3>Come aprire l’ombrellone</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Sollevate la maniglia.</strong> Tirate la maniglia verso l’alto fino allo scatto finale, portandola all’ultimo foro disponibile.</li>\r\n<li><strong>Aprite l’ombrellone con la manovella.</strong> Girate la manovella lentamente, controllando sempre che i bracci dell’ombrellone non tocchino nulla durante l’apertura.</li>\r\n<li><strong>Fermatevi quando la manovella si blocca.</strong> Continuate a girare solo fino a quando si blocca o diventa dura. A quel punto non forzate.</li>\r\n<li><strong>Regolate la posizione.</strong> Se necessario, potete sistemare meglio l’ombrellone dopo l’apertura.</li>\r\n<li><strong>Per spostarlo lateralmente:</strong> premete con il piede il pedale alla base e, tenendolo premuto, muovete l’ombrellone in orizzontale con la maniglia fino alla posizione desiderata.</li>\r\n</ol>\r\n<h3>Come chiudere l’ombrellone</h3>\r\n<ol class=\"step-list\">\r\n<li>Se l’ombrellone è stato spostato lateralmente, riportatelo prima nella posizione iniziale usando il pedale e la maniglia.</li>\r\n<li>Girate la manovella nel senso opposto fino alla completa chiusura dell’ombrellone.</li>\r\n<li>Accompagnate la maniglia verso il basso fino alla posizione di riposo.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Responsabilità:</strong> per preservare l’ombrellone, vi chiediamo di richiuderlo sempre quando uscite di casa e in caso di vento o maltempo. Eventuali danni dovuti a un uso non corretto o al fatto di averlo lasciato aperto in assenza degli ospiti restano sotto la responsabilità di chi soggiorna.</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<div class=\"warning-box\"><strong>Important:</strong> before opening the umbrella, make sure there is enough free space around it and that the arms do not touch plants, walls, chairs or other objects. Never force the handle, crank or pedal.</div>\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Guida visiva per aprire e chiudere l’ombrellone da giardino\" src=\"/assets/manuale-ombrellone.png\"/>\r\n</div>\r\n<h3>How to open the umbrella</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Raise the handle.</strong> Pull the handle upward until the final click, bringing it to the highest available hole.</li>\r\n<li><strong>Open the umbrella with the crank.</strong> Turn the crank slowly, always checking that the umbrella arms do not touch anything while opening.</li>\r\n<li><strong>Stop when the crank locks.</strong> Keep turning only until it locks or becomes hard to turn. Do not force it.</li>\r\n<li><strong>Adjust the position.</strong> If needed, you can fine-tune the umbrella after opening.</li>\r\n<li><strong>To move it sideways:</strong> press the pedal at the base with your foot and, while keeping it pressed, move the umbrella horizontally with the handle until it reaches the desired position.</li>\r\n</ol>\r\n<h3>How to close the umbrella</h3>\r\n<ol class=\"step-list\">\r\n<li>If the umbrella has been moved sideways, first return it to its starting position using the pedal and the handle.</li>\r\n<li>Turn the crank in the opposite direction until the umbrella is completely closed.</li>\r\n<li>Guide the handle downward until it returns to the resting position.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Responsibility:</strong> to protect the umbrella, please always close it when leaving the house and in case of wind or bad weather. Any damage caused by improper use or by leaving it open while guests are away remains the responsibility of the guests.</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<div class=\"warning-box\"><strong>Importante:</strong> antes de abrir la sombrilla, aseguraos de que haya suficiente espacio libre alrededor y de que los brazos no toquen plantas, paredes, sillas u otros objetos. No forcéis nunca la manija, la manivela ni el pedal.</div>\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Guida visiva per aprire e chiudere l’ombrellone da giardino\" src=\"/assets/manuale-ombrellone.png\"/>\r\n</div>\r\n<h3>Cómo abrir la sombrilla</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Levantad la manija.</strong> Tirad de la manija hacia arriba hasta el clic final, llevándola hasta el último orificio disponible.</li>\r\n<li><strong>Abrid la sombrilla con la manivela.</strong> Girad la manivela lentamente, comprobando siempre que los brazos de la sombrilla no toquen nada durante la apertura.</li>\r\n<li><strong>Deteneos cuando la manivela se bloquee.</strong> Seguid girando solo hasta que se bloquee o se ponga dura. No la forcéis.</li>\r\n<li><strong>Ajustad la posición.</strong> Si es necesario, podéis ajustar mejor la sombrilla después de abrirla.</li>\r\n<li><strong>Para moverla lateralmente:</strong> presionad con el pie el pedal de la base y, manteniéndolo pulsado, moved la sombrilla en horizontal con la manija hasta la posición deseada.</li>\r\n</ol>\r\n<h3>Cómo cerrar la sombrilla</h3>\r\n<ol class=\"step-list\">\r\n<li>Si la sombrilla se ha desplazado lateralmente, volved primero a la posición inicial usando el pedal y la manija.</li>\r\n<li>Girad la manivela en el sentido contrario hasta que la sombrilla se cierre por completo.</li>\r\n<li>Acompañad la manija hacia abajo hasta la posición de reposo.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Responsabilidad:</strong> para proteger la sombrilla, os pedimos que la cerréis siempre al salir de casa y en caso de viento o mal tiempo. Cualquier daño causado por un uso incorrecto o por dejarla abierta cuando no estéis en casa será responsabilidad de los huéspedes.</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<div class=\"warning-box\"><strong>Important :</strong> avant d’ouvrir le parasol, assurez-vous qu’il y ait suffisamment d’espace autour et que les bras ne touchent ni plantes, ni murs, ni chaises, ni autres objets. Ne forcez jamais la poignée, la manivelle ou la pédale.</div>\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Guida visiva per aprire e chiudere l’ombrellone da giardino\" src=\"/assets/manuale-ombrellone.png\"/>\r\n</div>\r\n<h3>Comment ouvrir le parasol</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Relevez la poignée.</strong> Tirez la poignée vers le haut jusqu’au déclic final, en l’amenant jusqu’au dernier trou disponible.</li>\r\n<li><strong>Ouvrez le parasol avec la manivelle.</strong> Tournez la manivelle lentement en vérifiant toujours que les bras du parasol ne touchent rien pendant l’ouverture.</li>\r\n<li><strong>Arrêtez-vous lorsque la manivelle se bloque.</strong> Continuez à tourner seulement jusqu’à ce qu’elle se bloque ou devienne dure. Ne forcez pas.</li>\r\n<li><strong>Réglez la position.</strong> Si nécessaire, vous pouvez mieux ajuster le parasol après l’ouverture.</li>\r\n<li><strong>Pour le déplacer latéralement :</strong> appuyez avec le pied sur la pédale à la base et, en la maintenant enfoncée, déplacez le parasol horizontalement à l’aide de la poignée jusqu’à la position souhaitée.</li>\r\n</ol>\r\n<h3>Comment fermer le parasol</h3>\r\n<ol class=\"step-list\">\r\n<li>Si le parasol a été déplacé latéralement, remettez-le d’abord dans sa position initiale à l’aide de la pédale et de la poignée.</li>\r\n<li>Tournez la manivelle dans le sens opposé jusqu’à la fermeture complète du parasol.</li>\r\n<li>Accompagnez la poignée vers le bas jusqu’à la position de repos.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Responsabilité :</strong> pour préserver le parasol, nous vous demandons de toujours le refermer lorsque vous quittez la maison et en cas de vent ou de mauvais temps. Tout dommage causé par une mauvaise utilisation ou par le fait de l’avoir laissé ouvert en l’absence des occupants reste à la charge des hôtes.</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<div class=\"warning-box\"><strong>Wichtig:</strong> bevor ihr den Schirm öffnet, stellt sicher, dass um ihn herum genügend freier Platz ist und dass die Arme keine Pflanzen, Wände, Stühle oder andere Gegenstände berühren. Übt niemals Gewalt auf Griff, Kurbel oder Pedal aus.</div>\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Guida visiva per aprire e chiudere l’ombrellone da giardino\" src=\"/assets/manuale-ombrellone.png\"/>\r\n</div>\r\n<h3>So öffnet ihr den Schirm</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Hebt den Griff an.</strong> Zieht den Griff nach oben, bis zum endgültigen Einrasten, und bringt ihn in das letzte verfügbare Loch.</li>\r\n<li><strong>Öffnet den Schirm mit der Kurbel.</strong> Dreht die Kurbel langsam und prüft dabei immer, dass die Arme des Schirms beim Öffnen nichts berühren.</li>\r\n<li><strong>Hört auf, wenn sich die Kurbel blockiert.</strong> Dreht nur weiter, bis sie sich blockiert oder schwer zu drehen ist. Übt dann keine Gewalt aus.</li>\r\n<li><strong>Stellt die Position ein.</strong> Bei Bedarf könnt ihr den Schirm nach dem Öffnen besser ausrichten.</li>\r\n<li><strong>Um ihn seitlich zu verschieben:</strong> drückt mit dem Fuß das Pedal an der Basis und verschiebt, während ihr es gedrückt haltet, den Schirm mit dem Griff horizontal bis zur gewünschten Position.</li>\r\n</ol>\r\n<h3>So schließt ihr den Schirm</h3>\r\n<ol class=\"step-list\">\r\n<li>Wenn der Schirm seitlich verschoben wurde, bringt ihn zuerst mit dem Pedal und dem Griff in die Ausgangsposition zurück.</li>\r\n<li>Dreht die Kurbel in die entgegengesetzte Richtung, bis der Schirm vollständig geschlossen ist.</li>\r\n<li>Führt den Griff nach unten, bis er in die Ruheposition zurückkehrt.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Verantwortung:</strong> um den Schirm zu erhalten, bitten wir euch, ihn immer wieder zu schließen, wenn ihr das Haus verlasst, und bei Wind oder schlechtem Wetter. Schäden durch unsachgemäße Nutzung oder dadurch, dass er in Abwesenheit der Gäste offen gelassen wurde, liegen in der Verantwortung der Gäste.</div>\r\n</div>\r\n</details>"}},{"id":"moka","index":"006","icon":"Coffee","image":"assets/manuale-moka.jpg","tag":{"it":"Moka","en":"Moka","es":"Moka","fr":"Moka","de":"Moka"},"title":{"it":"Moka e caffè","en":"Moka coffee maker","es":"Cafetera moka","fr":"Cafetière moka","de":"Moka-Kanne und Kaffee"},"body":{"it":"<div class=\"manual-content\">\r\n<div aria-label=\"Scegli il tipo di moka\" class=\"moka-choice\" role=\"group\">\r\n<p>Scegliete quale istruzione volete aprire:</p>\r\n<div class=\"moka-choice-buttons\">\r\n<button class=\"moka-choice-button\" data-moka-target=\"traditionalMoka\" type=\"button\">Moka tradizionale</button>\r\n<button class=\"moka-choice-button\" data-moka-target=\"podMoka\" type=\"button\">Moka con le capsule</button>\r\n</div>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"traditionalMoka\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Istruzioni per usare la moka\" src=\"/assets/manuale-moka.jpg\"/>\r\n</div>\r\n<div class=\"warning-box\"><strong>Attenzione:</strong> la moka non va mai messa in lavastoviglie. Non usate detersivi aggressivi. Lavatela solo a mano con acqua calda, asciugatela bene dopo il lavaggio e non lasciate acqua nel serbatoio.</div>\r\n<h3>Moka tradizionale</h3>\r\n<h3>Come preparare il caffè con la moka</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Svitate la moka.</strong> Separate la parte inferiore, il filtro e la parte superiore.</li>\r\n<li><strong>Riempite la parte inferiore con acqua.</strong> L’acqua deve arrivare sotto la valvola, senza superarla. <strong>Inserite il filtro.</strong> Poi aggiungete il caffè macinato nel filtro. <strong>Non pressate troppo il caffè.</strong> Livellatelo delicatamente, senza schiacciarlo.</li>\r\n<li><strong>Chiudete bene la moka.</strong> Avvitate la parte superiore alla base. <strong>Mettete la moka sul fornello.</strong> Usate fuoco basso o medio, mai troppo alto.</li>\r\n<li><strong>Aspettate che il caffè salga.</strong> Quando sentite il classico rumore della moka, il caffè sta riempiendo la parte superiore. <strong>Spegnete il fuoco.</strong> Appena il caffè è salito, togliete la moka dal fornello o spegnete subito la fiamma.</li>\r\n<li><strong>Versate e gustate il caffè.</strong> Fate attenzione perché la moka sarà molto calda.</li>\r\n</ol>\r\n<h3>Dopo l’utilizzo</h3>\r\n<ul class=\"simple-list\">\r\n<li>Lasciate raffreddare completamente la moka prima di lavarla.</li>\r\n<li>Lavatela solo a mano con acqua calda. Non mettetela in lavastoviglie.</li>\r\n<li>Asciugatela bene dopo il lavaggio, soprattutto il serbatoio dell’acqua.</li>\r\n<li>Non lasciate acqua nel serbatoio.</li>\r\n</ul>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"podMoka\">\r\n<h3>Moka con le capsule</h3>\r\n<p>La MokaCiao funziona con le cialde. Seguite le immagini nella vostra lingua per preparare il caffè e smaltire correttamente la cialda.</p>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni Borbone italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/borboneitalianoinglese.jpeg\"/>\r\n<img alt=\"Instrucciones Borbone en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/borbonespagnolo.jpeg\"/>\r\n<img alt=\"Instructions Borbone en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/borbonefrancese.jpeg\"/>\r\n<img alt=\"Borbone-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/borbonetedesco.jpeg\"/>\r\n</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Spiegazione MokaCiao in italiano\" class=\"moka-language-image\" data-langs=\"it\" src=\"/assets/spiegazioneitaliano.jpeg\"/>\r\n<img alt=\"MokaCiao explanation in English\" class=\"moka-language-image\" data-langs=\"en\" src=\"/assets/spiegazioneinglese.jpeg\"/>\r\n<img alt=\"Explicación MokaCiao en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/spiegazionespagnolo.jpeg\"/>\r\n<img alt=\"Explication MokaCiao en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/spiegazionefrancese.jpeg\"/>\r\n<img alt=\"MokaCiao-Erklärung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/spiegazionetedesco.jpeg\"/>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<div aria-label=\"Scegli il tipo di moka\" class=\"moka-choice\" role=\"group\">\r\n<p>Choose which instructions you want to open:</p>\r\n<div class=\"moka-choice-buttons\">\r\n<button class=\"moka-choice-button\" data-moka-target=\"traditionalMoka\" type=\"button\">Traditional moka pot</button>\r\n<button class=\"moka-choice-button\" data-moka-target=\"podMoka\" type=\"button\">Pod moka coffee maker</button>\r\n</div>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"traditionalMoka\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Istruzioni per usare la moka\" src=\"/assets/manuale-moka.jpg\"/>\r\n</div>\r\n<div class=\"warning-box\"><strong>Attention:</strong> never put the moka in the dishwasher. Do not use harsh detergents. Hand wash it only with hot water, dry it thoroughly after washing and do not leave water in the tank.</div>\r\n<h3>Traditional moka pot</h3>\r\n<h3>How to make coffee with the moka</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Unscrew the moka.</strong> Separate the lower chamber, the filter and the upper part.</li>\r\n<li><strong>Fill the lower chamber with water.</strong> The water should reach just below the valve, without going above it. <strong>Insert the filter.</strong> Then add ground coffee into the filter. <strong>Do not press the coffee too much.</strong> Level it gently without compacting it.</li>\r\n<li><strong>Close the moka properly.</strong> Screw the upper part onto the base. <strong>Place the moka on the stove.</strong> Use low or medium heat, never too high.</li>\r\n<li><strong>Wait for the coffee to come up.</strong> When you hear the classic moka bubbling sound, the coffee is filling the upper chamber. <strong>Turn off the heat.</strong> As soon as the coffee has come up, remove the moka from the stove or turn off the heat immediately.</li>\r\n<li><strong>Pour and enjoy the coffee.</strong> Be careful because the moka will be very hot.</li>\r\n</ol>\r\n<h3>After use</h3>\r\n<ul class=\"simple-list\">\r\n<li>Let the moka cool down completely before washing it.</li>\r\n<li>Hand wash it only with hot water. Do not put it in the dishwasher.</li>\r\n<li>Dry it thoroughly after washing, especially the water tank.</li>\r\n<li>Do not leave water in the tank.</li>\r\n</ul>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"podMoka\">\r\n<h3>Pod moka coffee maker</h3>\r\n<p>MokaCiao uses coffee pods. Follow the images in your language to prepare the coffee and dispose of the pod correctly.</p>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni Borbone italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/borboneitalianoinglese.jpeg\"/>\r\n<img alt=\"Instrucciones Borbone en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/borbonespagnolo.jpeg\"/>\r\n<img alt=\"Instructions Borbone en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/borbonefrancese.jpeg\"/>\r\n<img alt=\"Borbone-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/borbonetedesco.jpeg\"/>\r\n</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Spiegazione MokaCiao in italiano\" class=\"moka-language-image\" data-langs=\"it\" src=\"/assets/spiegazioneitaliano.jpeg\"/>\r\n<img alt=\"MokaCiao explanation in English\" class=\"moka-language-image\" data-langs=\"en\" src=\"/assets/spiegazioneinglese.jpeg\"/>\r\n<img alt=\"Explicación MokaCiao en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/spiegazionespagnolo.jpeg\"/>\r\n<img alt=\"Explication MokaCiao en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/spiegazionefrancese.jpeg\"/>\r\n<img alt=\"MokaCiao-Erklärung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/spiegazionetedesco.jpeg\"/>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<div aria-label=\"Scegli il tipo di moka\" class=\"moka-choice\" role=\"group\">\r\n<p>Elegid qué instrucciones queréis abrir:</p>\r\n<div class=\"moka-choice-buttons\">\r\n<button class=\"moka-choice-button\" data-moka-target=\"traditionalMoka\" type=\"button\">Cafetera moka tradicional</button>\r\n<button class=\"moka-choice-button\" data-moka-target=\"podMoka\" type=\"button\">Cafetera moka con cápsulas</button>\r\n</div>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"traditionalMoka\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Istruzioni per usare la moka\" src=\"/assets/manuale-moka.jpg\"/>\r\n</div>\r\n<div class=\"warning-box\"><strong>Atención:</strong> la cafetera moka no debe ponerse nunca en el lavavajillas. No uséis detergentes agresivos. Lavadla solo a mano con agua caliente, secadla bien después del lavado y no dejéis agua en el depósito.</div>\r\n<h3>Cafetera moka tradicional</h3>\r\n<h3>Cómo preparar café con la moka</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Desenroscad la moka.</strong> Separad la parte inferior, el filtro y la parte superior.</li>\r\n<li><strong>Llenad la parte inferior con agua.</strong> El agua debe llegar justo por debajo de la válvula, sin superarla. <strong>Colocad el filtro.</strong> Luego añadid café molido en el filtro. <strong>No presionéis demasiado el café.</strong> Niveladlo suavemente, sin compactarlo.</li>\r\n<li><strong>Cerrad bien la moka.</strong> Enroscad la parte superior a la base. <strong>Poned la moka en el fuego.</strong> Usad fuego bajo o medio, nunca demasiado alto.</li>\r\n<li><strong>Esperad a que suba el café.</strong> Cuando escuchéis el sonido típico de la moka, el café está llenando la parte superior. <strong>Apagad el fuego.</strong> En cuanto el café haya subido, quitad la moka del fuego o apagadlo enseguida.</li>\r\n<li><strong>Servid y disfrutad el café.</strong> Tened cuidado porque la moka estará muy caliente.</li>\r\n</ol>\r\n<h3>Después del uso</h3>\r\n<ul class=\"simple-list\">\r\n<li>Dejad que la moka se enfríe completamente antes de lavarla.</li>\r\n<li>Lavadla solo a mano con agua caliente. No la metáis en el lavavajillas.</li>\r\n<li>Secadla bien después del lavado, especialmente el depósito del agua.</li>\r\n<li>No dejéis agua en el depósito.</li>\r\n</ul>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"podMoka\">\r\n<h3>Cafetera moka con cápsulas</h3>\r\n<p>MokaCiao funciona con cápsulas de café. Seguid las imágenes en vuestro idioma para preparar el café y desechar correctamente la cápsula.</p>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni Borbone italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/borboneitalianoinglese.jpeg\"/>\r\n<img alt=\"Instrucciones Borbone en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/borbonespagnolo.jpeg\"/>\r\n<img alt=\"Instructions Borbone en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/borbonefrancese.jpeg\"/>\r\n<img alt=\"Borbone-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/borbonetedesco.jpeg\"/>\r\n</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Spiegazione MokaCiao in italiano\" class=\"moka-language-image\" data-langs=\"it\" src=\"/assets/spiegazioneitaliano.jpeg\"/>\r\n<img alt=\"MokaCiao explanation in English\" class=\"moka-language-image\" data-langs=\"en\" src=\"/assets/spiegazioneinglese.jpeg\"/>\r\n<img alt=\"Explicación MokaCiao en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/spiegazionespagnolo.jpeg\"/>\r\n<img alt=\"Explication MokaCiao en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/spiegazionefrancese.jpeg\"/>\r\n<img alt=\"MokaCiao-Erklärung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/spiegazionetedesco.jpeg\"/>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<div aria-label=\"Scegli il tipo di moka\" class=\"moka-choice\" role=\"group\">\r\n<p>Choisissez les instructions que vous souhaitez ouvrir :</p>\r\n<div class=\"moka-choice-buttons\">\r\n<button class=\"moka-choice-button\" data-moka-target=\"traditionalMoka\" type=\"button\">Cafetière moka traditionnelle</button>\r\n<button class=\"moka-choice-button\" data-moka-target=\"podMoka\" type=\"button\">Cafetière moka à dosettes</button>\r\n</div>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"traditionalMoka\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Istruzioni per usare la moka\" src=\"/assets/manuale-moka.jpg\"/>\r\n</div>\r\n<div class=\"warning-box\"><strong>Attention :</strong> ne mettez jamais la moka au lave-vaisselle. N’utilisez pas de détergents agressifs. Lavez-la uniquement à la main avec de l’eau chaude, séchez-la bien après le lavage et ne laissez pas d’eau dans le réservoir.</div>\r\n<h3>Cafetière moka traditionnelle</h3>\r\n<h3>Comment préparer le café avec la moka</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Dévissez la moka.</strong> Séparez la partie inférieure, le filtre et la partie supérieure.</li>\r\n<li><strong>Remplissez la partie inférieure avec de l’eau.</strong> L’eau doit arriver juste sous la valve, sans la dépasser. <strong>Insérez le filtre.</strong> Puis ajoutez le café moulu dans le filtre. <strong>Ne tassez pas trop le café.</strong> Égalisez-le doucement, sans le compacter.</li>\r\n<li><strong>Fermez bien la moka.</strong> Vissez la partie supérieure sur la base. <strong>Placez la moka sur la plaque.</strong> Utilisez un feu doux ou moyen, jamais trop fort.</li>\r\n<li><strong>Attendez que le café monte.</strong> Lorsque vous entendez le bruit typique de la moka, le café remplit la partie supérieure. <strong>Éteignez le feu.</strong> Dès que le café est monté, retirez la moka de la plaque ou éteignez immédiatement le feu.</li>\r\n<li><strong>Servez et dégustez le café.</strong> Attention, la moka sera très chaude.</li>\r\n</ol>\r\n<h3>Après utilisation</h3>\r\n<ul class=\"simple-list\">\r\n<li>Laissez la moka refroidir complètement avant de la laver.</li>\r\n<li>Lavez-la uniquement à la main avec de l’eau chaude. Ne la mettez pas au lave-vaisselle.</li>\r\n<li>Séchez-la bien après le lavage, surtout le réservoir d’eau.</li>\r\n<li>Ne laissez pas d’eau dans le réservoir.</li>\r\n</ul>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"podMoka\">\r\n<h3>Cafetière moka à dosettes</h3>\r\n<p>MokaCiao fonctionne avec des dosettes de café. Suivez les images dans votre langue pour préparer le café et jeter correctement la dosette.</p>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni Borbone italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/borboneitalianoinglese.jpeg\"/>\r\n<img alt=\"Instrucciones Borbone en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/borbonespagnolo.jpeg\"/>\r\n<img alt=\"Instructions Borbone en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/borbonefrancese.jpeg\"/>\r\n<img alt=\"Borbone-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/borbonetedesco.jpeg\"/>\r\n</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Spiegazione MokaCiao in italiano\" class=\"moka-language-image\" data-langs=\"it\" src=\"/assets/spiegazioneitaliano.jpeg\"/>\r\n<img alt=\"MokaCiao explanation in English\" class=\"moka-language-image\" data-langs=\"en\" src=\"/assets/spiegazioneinglese.jpeg\"/>\r\n<img alt=\"Explicación MokaCiao en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/spiegazionespagnolo.jpeg\"/>\r\n<img alt=\"Explication MokaCiao en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/spiegazionefrancese.jpeg\"/>\r\n<img alt=\"MokaCiao-Erklärung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/spiegazionetedesco.jpeg\"/>\r\n</div>\r\n</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<div aria-label=\"Scegli il tipo di moka\" class=\"moka-choice\" role=\"group\">\r\n<p>Wählt aus, welche Anleitung ihr öffnen möchtet:</p>\r\n<div class=\"moka-choice-buttons\">\r\n<button class=\"moka-choice-button\" data-moka-target=\"traditionalMoka\" type=\"button\">Traditionelle Moka-Kanne</button>\r\n<button class=\"moka-choice-button\" data-moka-target=\"podMoka\" type=\"button\">Moka-Kanne mit Pads</button>\r\n</div>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"traditionalMoka\">\r\n<div class=\"manual-img contain\">\r\n<img alt=\"Istruzioni per usare la moka\" src=\"/assets/manuale-moka.jpg\"/>\r\n</div>\r\n<div class=\"warning-box\"><strong>Achtung:</strong> die Moka-Kanne darf niemals in die Spülmaschine gestellt werden. Verwendet keine aggressiven Reinigungsmittel. Wascht sie nur von Hand mit heißem Wasser, trocknet sie nach dem Waschen gut ab und lasst kein Wasser im Tank.</div>\r\n<h3>Traditionelle Moka-Kanne</h3>\r\n<h3>So bereitet ihr Kaffee mit der Moka-Kanne zu</h3>\r\n<ol class=\"step-list\">\r\n<li><strong>Schraubt die Moka-Kanne auf.</strong> Trennt den unteren Teil, den Filter und den oberen Teil.</li>\r\n<li><strong>Füllt den unteren Teil mit Wasser.</strong> Das Wasser muss bis knapp unter das Ventil reichen, ohne es zu überschreiten. <strong>Setzt den Filter ein.</strong> Dann gebt den gemahlenen Kaffee in den Filter. <strong>Presst den Kaffee nicht zu stark.</strong> Verteilt ihn vorsichtig, ohne ihn zu verdichten.</li>\r\n<li><strong>Verschließt die Moka-Kanne gut.</strong> Schraubt den oberen Teil auf die Basis. <strong>Stellt die Moka-Kanne auf den Herd.</strong> Verwendet niedrige oder mittlere Hitze, niemals zu hoch.</li>\r\n<li><strong>Wartet, bis der Kaffee aufsteigt.</strong> Wenn ihr das typische Geräusch der Moka-Kanne hört, füllt der Kaffee den oberen Teil. <strong>Schaltet die Hitze aus.</strong> Sobald der Kaffee aufgestiegen ist, nehmt die Moka-Kanne vom Herd oder schaltet die Flamme sofort aus.</li>\r\n<li><strong>Gießt den Kaffee aus und genießt ihn.</strong> Seid vorsichtig, denn die Moka-Kanne wird sehr heiß.</li>\r\n</ol>\r\n<h3>Nach der Benutzung</h3>\r\n<ul class=\"simple-list\">\r\n<li>Lasst die Moka-Kanne vollständig abkühlen, bevor ihr sie wascht.</li>\r\n<li>Wascht sie nur von Hand mit heißem Wasser. Stellt sie nicht in die Spülmaschine.</li>\r\n<li>Trocknet sie nach dem Waschen gut ab, besonders den Wassertank.</li>\r\n<li>Lasst kein Wasser im Tank.</li>\r\n</ul>\r\n</div>\r\n<div class=\"moka-option\" hidden=\"\" id=\"podMoka\">\r\n<h3>Moka-Kanne mit Pads</h3>\r\n<p>MokaCiao funktioniert mit Kaffeepads. Folgt den Bildern in eurer Sprache, um den Kaffee zuzubereiten und das Pad richtig zu entsorgen.</p>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni Borbone italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/borboneitalianoinglese.jpeg\"/>\r\n<img alt=\"Instrucciones Borbone en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/borbonespagnolo.jpeg\"/>\r\n<img alt=\"Instructions Borbone en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/borbonefrancese.jpeg\"/>\r\n<img alt=\"Borbone-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/borbonetedesco.jpeg\"/>\r\n</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Spiegazione MokaCiao in italiano\" class=\"moka-language-image\" data-langs=\"it\" src=\"/assets/spiegazioneitaliano.jpeg\"/>\r\n<img alt=\"MokaCiao explanation in English\" class=\"moka-language-image\" data-langs=\"en\" src=\"/assets/spiegazioneinglese.jpeg\"/>\r\n<img alt=\"Explicación MokaCiao en español\" class=\"moka-language-image\" data-langs=\"es\" src=\"/assets/spiegazionespagnolo.jpeg\"/>\r\n<img alt=\"Explication MokaCiao en français\" class=\"moka-language-image\" data-langs=\"fr\" src=\"/assets/spiegazionefrancese.jpeg\"/>\r\n<img alt=\"MokaCiao-Erklärung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/spiegazionetedesco.jpeg\"/>\r\n</div>\r\n</div>\r\n</div>\r\n</details>"}},{"id":"manual-6","index":"007","icon":"CookingPot","image":null,"tag":{"it":"Cucina","en":"Kitchen","es":"Cocina","fr":"Cuisine","de":"Küche"},"title":{"it":"Cucina e piano cottura","en":"Kitchen and hob","es":"Cocina y placa","fr":"Cuisine et plaque de cuisson","de":"Küche und Herd"},"body":{"it":"<div class=\"manual-content\">\r\n<ul class=\"simple-list\">\r\n<li>Potete usare la cucina normalmente, avendo cura di lasciare tutto pulito dopo l'utilizzo.</li>\r\n<li>Non lasciate pentole, moka o padelle sul fuoco senza controllo.</li>\r\n<li>Prima di uscire o prima del check-out, controllate che il piano cottura sia spento.</li>\r\n</ul>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<ul class=\"simple-list\">\r\n<li>You can use the kitchen normally, taking care to leave everything clean after use.</li>\r\n<li>Do not leave pots, the moka or pans on the stove unattended.</li>\r\n<li>Before going out or before check-out, make sure the hob is turned off.</li>\r\n</ul>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<ul class=\"simple-list\">\r\n<li>Podéis usar la cocina normalmente, procurando dejar todo limpio después de usarla.</li>\r\n<li>No dejéis ollas, moka o sartenes en el fuego sin vigilancia.</li>\r\n<li>Antes de salir o antes del check-out, comprobad que la placa esté apagada.</li>\r\n</ul>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<ul class=\"simple-list\">\r\n<li>Vous pouvez utiliser la cuisine normalement, en veillant à tout laisser propre après utilisation.</li>\r\n<li>Ne laissez pas casseroles, moka ou poêles sur le feu sans surveillance.</li>\r\n<li>Avant de sortir ou avant le check-out, vérifiez que la plaque de cuisson est éteinte.</li>\r\n</ul>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<ul class=\"simple-list\">\r\n<li>Ihr könnt die Küche normal benutzen, achtet aber darauf, nach der Benutzung alles sauber zu hinterlassen.</li>\r\n<li>Lasst Töpfe, Moka-Kanne oder Pfannen nicht unbeaufsichtigt auf dem Herd.</li>\r\n<li>Bevor ihr ausgeht oder vor dem Check-out, prüft, dass der Herd ausgeschaltet ist.</li>\r\n</ul>\r\n</div>\r\n</details>"}},{"id":"manual-7","index":"008","icon":"WashingMachine","image":"assets/manuale-lavatrice-comandi.jpg","tag":{"it":"Lavatrice","en":"Washing machine","es":"Lavadora","fr":"Lave-linge","de":"Waschmaschine"},"title":{"it":"Lavatrice","en":"Washing machine","es":"Lavadora","fr":"Machine à laver","de":"Waschmaschine"},"body":{"it":"<div class=\"manual-content\">\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Comandi della lavatrice\" src=\"/assets/manuale-lavatrice-comandi.jpg\"/>\r\n</div>\r\n<h3>Comandi principali</h3>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto ON/OFF</strong>\r\n<p>Serve per accendere e spegnere la lavatrice.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Manopola programmi</strong>\r\n<p>Serve per scegliere il programma di lavaggio. Giratela fino al numero desiderato, seguendo la tabella dei programmi.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Manopola temperatura</strong>\r\n<p>Serve per scegliere la temperatura dell’acqua: 20°, 30°, 40°, 50°, 60°, 70° o 90°. Per un lavaggio normale consigliamo 30° o 40°.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Manopola centrifuga</strong>\r\n<p>Serve per scegliere la velocità della centrifuga. Più alto è il numero, più i capi usciranno strizzati. Per un uso normale potete lasciare 700/800 giri.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto START/PAUSE</strong>\r\n<p>Serve per avviare il lavaggio o metterlo in pausa.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto EcoTime</strong>\r\n<p>Può essere usato per ridurre tempo o consumi nei lavaggi più leggeri. Non è indispensabile: se avete dubbi, potete non usarlo.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto Energy Saver</strong>\r\n<p>Serve per un lavaggio più attento ai consumi. Può allungare i tempi del lavaggio. Usatelo solo se vi serve.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto extra risciacquo</strong>\r\n<p>È il tasto con il simbolo delle gocce. Aggiunge un risciacquo in più, utile se avete usato troppo detersivo o per capi delicati.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Tasto avvio ritardato</strong>\r\n<p>È il tasto con il simbolo dell’orologio. Serve per far partire la lavatrice dopo 3, 6, 9 o 12 ore. Per un uso normale non serve.</p>\r\n</div>\r\n</div>\r\n<p>La lavatrice può essere usata se necessario. Vi chiediamo solo di non sovraccaricarla e di usare poco detersivo.</p>\r\n<h3>Dove mettere il detersivo</h3>\r\n<div class=\"manual-img small\">\r\n<img alt=\"Cassetto detersivi della lavatrice\" src=\"/assets/manuale-lavatrice-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Vaschetta 2:</strong> detersivo per il lavaggio principale. È quella da usare nella maggior parte dei casi.</li>\r\n<li><strong>Vaschetta con il fiore:</strong> ammorbidente, solo se volete usarlo.</li>\r\n<li><strong>Vaschetta 1:</strong> prelavaggio. Normalmente non serve.</li>\r\n</ul>\r\n<h3>Programmi principali</h3>\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Programmi della lavatrice\" src=\"/assets/manuale-lavatrice-programmi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programma</th>\r\n<th>Quando usarlo</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1 - Cotone 90°</td>\r\n<td>Per capi bianchi molto resistenti e molto sporchi. Usatelo raramente.</td>\r\n</tr>\r\n<tr>\r\n<td>2 - Cotone 60°</td>\r\n<td>Per asciugamani, lenzuola e capi resistenti.</td>\r\n</tr>\r\n<tr>\r\n<td>3 - Cotone 40°</td>\r\n<td>Scelta consigliata per un lavaggio normale di tutti i giorni.</td>\r\n</tr>\r\n<tr>\r\n<td>4 - Sintetici 60°</td>\r\n<td>Per capi sintetici più resistenti.</td>\r\n</tr>\r\n<tr>\r\n<td>5 - Sintetici 40°</td>\r\n<td>Per capi sintetici normali. Buona scelta per vestiti non troppo sporchi.</td>\r\n</tr>\r\n<tr>\r\n<td>6 / 7 / 8 - Zone 20°</td>\r\n<td>Per lavaggi a bassa temperatura, capi poco sporchi o più delicati.</td>\r\n</tr>\r\n<tr>\r\n<td>9 / 10 / 11 - Special</td>\r\n<td>Programmi per capi particolari. Usateli solo se sapete quale programma vi serve.</td>\r\n</tr>\r\n<tr>\r\n<td>12 / 13 / 14 - Sport</td>\r\n<td>Per capi sportivi o scarpe, se necessario.</td>\r\n</tr>\r\n<tr>\r\n<td>Rinse</td>\r\n<td>Serve solo per risciacquare i capi, senza fare un lavaggio completo.</td>\r\n</tr>\r\n<tr>\r\n<td>Spin + Drain</td>\r\n<td>Serve per centrifugare e scaricare l’acqua. Utile se il bucato è ancora troppo bagnato.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"warning-box\"><strong>Consiglio:</strong> per un lavaggio normale usate il programma <strong>3 - Cotone 40°</strong> oppure <strong>5 - Sintetici 40°</strong>. Non sovraccaricate la lavatrice e usate poco detersivo.</div>\r\n<ol class=\"step-list\">\r\n<li>Inserite i capi nel cestello senza riempirlo troppo.</li>\r\n<li>Mettete poco detersivo nella vaschetta <strong>2</strong>.</li>\r\n<li>Accendete la lavatrice con il tasto <strong>ON/OFF</strong>.</li>\r\n<li>Scegliete il programma con la manopola grande.</li>\r\n<li>Premete <strong>START/PAUSE</strong> per avviare.</li>\r\n</ol>\r\n<div class=\"warning-box\">Alla fine del soggiorno, se potete, mettete gli asciugamani usati nella lavatrice <strong>senza avviarla</strong>.</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Comandi della lavatrice\" src=\"/assets/manuale-lavatrice-comandi.jpg\"/>\r\n</div>\r\n<h3>Main controls</h3>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>ON/OFF button</strong>\r\n<p>Use this button to turn the washing machine on and off.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Programme dial</strong>\r\n<p>Use it to choose the washing programme. Turn it to the desired number, following the programme table.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Temperature dial</strong>\r\n<p>Use it to choose the water temperature: 20°, 30°, 40°, 50°, 60°, 70° or 90°. For a normal wash, we recommend 30° or 40°.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Spin speed dial</strong>\r\n<p>Use it to choose the spin speed. The higher the number, the drier the clothes will come out. For normal use, you can leave it at 700/800 rpm.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>START/PAUSE button</strong>\r\n<p>Use this button to start the wash or pause it.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>EcoTime button</strong>\r\n<p>It can be used to reduce time or consumption for lighter washes. It is not essential: if you are not sure, you can avoid using it.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Energy Saver button</strong>\r\n<p>Use it for a more energy-saving wash. It may make the cycle longer. Use it only if needed.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Extra rinse button</strong>\r\n<p>It is the button with the drops symbol. It adds an extra rinse, useful if you used too much detergent or for delicate clothes.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Delayed start button</strong>\r\n<p>It is the button with the clock symbol. It starts the washing machine after 3, 6, 9 or 12 hours. For normal use, you do not need it.</p>\r\n</div>\r\n</div>\r\n<p>The washing machine can be used if needed. We only ask you not to overload it and to use a small amount of detergent.</p>\r\n<h3>Where to put the detergent</h3>\r\n<div class=\"manual-img small\">\r\n<img alt=\"Cassetto detersivi della lavatrice\" src=\"/assets/manuale-lavatrice-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Compartment 2:</strong> detergent for the main wash. This is the one to use in most cases.</li>\r\n<li><strong>Compartment with the flower:</strong> fabric softener, only if you want to use it.</li>\r\n<li><strong>Compartment 1:</strong> pre-wash. Usually not needed.</li>\r\n</ul>\r\n<h3>Main programmes</h3>\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Programmi della lavatrice\" src=\"/assets/manuale-lavatrice-programmi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programme</th>\r\n<th>When to use it</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1 - Cotton 90°</td>\r\n<td>For very resistant and very dirty white laundry. Use it rarely.</td>\r\n</tr>\r\n<tr>\r\n<td>2 - Cotton 60°</td>\r\n<td>For towels, sheets and resistant laundry.</td>\r\n</tr>\r\n<tr>\r\n<td>3 - Cotton 40°</td>\r\n<td>Recommended choice for a normal everyday wash.</td>\r\n</tr>\r\n<tr>\r\n<td>4 - Synthetics 60°</td>\r\n<td>For more resistant synthetic clothes.</td>\r\n</tr>\r\n<tr>\r\n<td>5 - Synthetics 40°</td>\r\n<td>For normal synthetic clothes. Good choice for clothes that are not too dirty.</td>\r\n</tr>\r\n<tr>\r\n<td>6 / 7 / 8 - Zone 20°</td>\r\n<td>For low-temperature washes, lightly soiled or more delicate clothes.</td>\r\n</tr>\r\n<tr>\r\n<td>9 / 10 / 11 - Special</td>\r\n<td>Programmes for specific garments. Use them only if you know which programme you need.</td>\r\n</tr>\r\n<tr>\r\n<td>12 / 13 / 14 - Sport</td>\r\n<td>For sportswear or shoes, if needed.</td>\r\n</tr>\r\n<tr>\r\n<td>Rinse</td>\r\n<td>Use it only to rinse clothes, without doing a full wash.</td>\r\n</tr>\r\n<tr>\r\n<td>Spin + Drain</td>\r\n<td>Use it to spin and drain water. Useful if the laundry is still too wet.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"warning-box\"><strong>Tip:</strong> for a normal wash, use programme <strong>3 - Cotton 40°</strong> or <strong>5 - Synthetics 40°</strong>. Do not overload the washing machine and use only a small amount of detergent.</div>\r\n<ol class=\"step-list\">\r\n<li>Put the clothes in the drum without overfilling it.</li>\r\n<li>Put a small amount of detergent in compartment <strong>2</strong>.</li>\r\n<li>Turn on the washing machine using the <strong>ON/OFF</strong> button.</li>\r\n<li>Choose the programme using the large dial.</li>\r\n<li>Press <strong>START/PAUSE</strong> to start.</li>\r\n</ol>\r\n<div class=\"warning-box\">At the end of your stay, if possible, place the used towels in the washing machine <strong>without starting it</strong>.</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Comandi della lavatrice\" src=\"/assets/manuale-lavatrice-comandi.jpg\"/>\r\n</div>\r\n<h3>Mandos principales</h3>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón ON/OFF</strong>\r\n<p>Sirve para encender y apagar la lavadora.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Rueda de programas</strong>\r\n<p>Sirve para elegir el programa de lavado. Giradla hasta el número deseado, siguiendo la tabla de programas.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Rueda de temperatura</strong>\r\n<p>Sirve para elegir la temperatura del agua: 20°, 30°, 40°, 50°, 60°, 70° o 90°. Para un lavado normal recomendamos 30° o 40°.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Rueda de centrifugado</strong>\r\n<p>Sirve para elegir la velocidad de centrifugado. Cuanto más alto sea el número, más escurrida saldrá la ropa. Para un uso normal podéis dejar 700/800 revoluciones.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón START/PAUSE</strong>\r\n<p>Sirve para iniciar el lavado o ponerlo en pausa.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón EcoTime</strong>\r\n<p>Puede usarse para reducir tiempo o consumo en lavados más ligeros. No es indispensable: si tenéis dudas, podéis no usarlo.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón Energy Saver</strong>\r\n<p>Sirve para un lavado con menor consumo. Puede alargar el tiempo del lavado. Usadlo solo si lo necesitáis.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón aclarado extra</strong>\r\n<p>Es el botón con el símbolo de las gotas. Añade un aclarado extra, útil si habéis usado demasiado detergente o para prendas delicadas.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Botón inicio diferido</strong>\r\n<p>Es el botón con el símbolo del reloj. Sirve para iniciar la lavadora después de 3, 6, 9 o 12 horas. Para un uso normal no hace falta.</p>\r\n</div>\r\n</div>\r\n<p>La lavadora puede usarse si es necesario. Solo os pedimos que no la sobrecarguéis y que uséis poco detergente.</p>\r\n<h3>Dónde poner el detergente</h3>\r\n<div class=\"manual-img small\">\r\n<img alt=\"Cassetto detersivi della lavatrice\" src=\"/assets/manuale-lavatrice-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Compartimento 2:</strong> detergente para el lavado principal. Es el que se usa en la mayoría de los casos.</li>\r\n<li><strong>Compartimento con la flor:</strong> suavizante, solo si queréis usarlo.</li>\r\n<li><strong>Compartimento 1:</strong> prelavado. Normalmente no hace falta.</li>\r\n</ul>\r\n<h3>Programas principales</h3>\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Programmi della lavatrice\" src=\"/assets/manuale-lavatrice-programmi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programa</th>\r\n<th>Cuándo usarlo</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1 - Algodón 90°</td>\r\n<td>Para prendas blancas muy resistentes y muy sucias. Usadlo raramente.</td>\r\n</tr>\r\n<tr>\r\n<td>2 - Algodón 60°</td>\r\n<td>Para toallas, sábanas y prendas resistentes.</td>\r\n</tr>\r\n<tr>\r\n<td>3 - Algodón 40°</td>\r\n<td>Opción recomendada para un lavado normal del día a día.</td>\r\n</tr>\r\n<tr>\r\n<td>4 - Sintéticos 60°</td>\r\n<td>Para prendas sintéticas más resistentes.</td>\r\n</tr>\r\n<tr>\r\n<td>5 - Sintéticos 40°</td>\r\n<td>Para prendas sintéticas normales. Buena opción para ropa no demasiado sucia.</td>\r\n</tr>\r\n<tr>\r\n<td>6 / 7 / 8 - Zone 20°</td>\r\n<td>Para lavados a baja temperatura, ropa poco sucia o más delicada.</td>\r\n</tr>\r\n<tr>\r\n<td>9 / 10 / 11 - Special</td>\r\n<td>Programas para prendas especiales. Usadlos solo si sabéis qué programa necesitáis.</td>\r\n</tr>\r\n<tr>\r\n<td>12 / 13 / 14 - Sport</td>\r\n<td>Para ropa deportiva o zapatos, si es necesario.</td>\r\n</tr>\r\n<tr>\r\n<td>Aclarado</td>\r\n<td>Sirve solo para aclarar la ropa, sin hacer un lavado completo.</td>\r\n</tr>\r\n<tr>\r\n<td>Centrifugado + desagüe</td>\r\n<td>Sirve para centrifugar y vaciar el agua. Útil si la ropa sigue demasiado mojada.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"warning-box\"><strong>Consejo:</strong> para un lavado normal, usad el programa <strong>3 - Algodón 40°</strong> o <strong>5 - Sintéticos 40°</strong>. No sobrecarguéis la lavadora y usad poco detergente.</div>\r\n<ol class=\"step-list\">\r\n<li>Meted la ropa en el tambor sin llenarlo demasiado.</li>\r\n<li>Poned poco detergente en el compartimento <strong>2</strong>.</li>\r\n<li>Encended la lavadora con el botón <strong>ON/OFF</strong>.</li>\r\n<li>Elegid el programa con la rueda grande.</li>\r\n<li>Pulsad <strong>START/PAUSE</strong> para iniciar.</li>\r\n</ol>\r\n<div class=\"warning-box\">Al final de la estancia, si podéis, poned las toallas usadas en la lavadora <strong>sin ponerla en marcha</strong>.</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Comandi della lavatrice\" src=\"/assets/manuale-lavatrice-comandi.jpg\"/>\r\n</div>\r\n<h3>Commandes principales</h3>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton ON/OFF</strong>\r\n<p>Il sert à allumer et éteindre la machine à laver.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Molette des programmes</strong>\r\n<p>Elle sert à choisir le programme de lavage. Tournez-la jusqu’au numéro souhaité, en suivant le tableau des programmes.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Molette de température</strong>\r\n<p>Elle sert à choisir la température de l’eau : 20°, 30°, 40°, 50°, 60°, 70° ou 90°. Pour un lavage normal, nous conseillons 30° ou 40°.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Molette d’essorage</strong>\r\n<p>Elle sert à choisir la vitesse d’essorage. Plus le nombre est élevé, plus le linge sort essoré. Pour un usage normal, vous pouvez laisser 700/800 tours.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton START/PAUSE</strong>\r\n<p>Il sert à lancer le lavage ou à le mettre en pause.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton EcoTime</strong>\r\n<p>Il peut être utilisé pour réduire le temps ou la consommation pour les lavages légers. Il n’est pas indispensable : en cas de doute, vous pouvez ne pas l’utiliser.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton Energy Saver</strong>\r\n<p>Il sert à un lavage plus économe. Il peut rallonger la durée du cycle. Utilisez-le seulement si nécessaire.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton rinçage supplémentaire</strong>\r\n<p>C’est le bouton avec le symbole des gouttes. Il ajoute un rinçage supplémentaire, utile si vous avez utilisé trop de lessive ou pour les vêtements délicats.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Bouton départ différé</strong>\r\n<p>C’est le bouton avec le symbole de l’horloge. Il sert à démarrer la machine après 3, 6, 9 ou 12 heures. Pour un usage normal, il n’est pas nécessaire.</p>\r\n</div>\r\n</div>\r\n<p>La machine à laver peut être utilisée si nécessaire. Nous vous demandons seulement de ne pas la surcharger et d’utiliser peu de lessive.</p>\r\n<h3>Où mettre la lessive</h3>\r\n<div class=\"manual-img small\">\r\n<img alt=\"Cassetto detersivi della lavatrice\" src=\"/assets/manuale-lavatrice-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Compartiment 2 :</strong> lessive pour le lavage principal. C’est celui à utiliser dans la plupart des cas.</li>\r\n<li><strong>Compartiment avec la fleur :</strong> adoucissant, seulement si vous voulez l’utiliser.</li>\r\n<li><strong>Compartiment 1 :</strong> prélavage. Normalement inutile.</li>\r\n</ul>\r\n<h3>Programmes principaux</h3>\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Programmi della lavatrice\" src=\"/assets/manuale-lavatrice-programmi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programme</th>\r\n<th>Quand l’utiliser</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1 - Coton 90°</td>\r\n<td>Pour linge blanc très résistant et très sale. À utiliser rarement.</td>\r\n</tr>\r\n<tr>\r\n<td>2 - Coton 60°</td>\r\n<td>Pour serviettes, draps et linge résistant.</td>\r\n</tr>\r\n<tr>\r\n<td>3 - Coton 40°</td>\r\n<td>Choix conseillé pour un lavage normal du quotidien.</td>\r\n</tr>\r\n<tr>\r\n<td>4 - Synthétiques 60°</td>\r\n<td>Pour vêtements synthétiques plus résistants.</td>\r\n</tr>\r\n<tr>\r\n<td>5 - Synthétiques 40°</td>\r\n<td>Pour vêtements synthétiques normaux. Bon choix pour du linge peu sale.</td>\r\n</tr>\r\n<tr>\r\n<td>6 / 7 / 8 - Zone 20°</td>\r\n<td>Pour les lavages à basse température, linge peu sale ou plus délicat.</td>\r\n</tr>\r\n<tr>\r\n<td>9 / 10 / 11 - Special</td>\r\n<td>Programmes pour vêtements particuliers. Utilisez-les seulement si vous savez quel programme vous faut.</td>\r\n</tr>\r\n<tr>\r\n<td>12 / 13 / 14 - Sport</td>\r\n<td>Pour vêtements de sport ou chaussures, si nécessaire.</td>\r\n</tr>\r\n<tr>\r\n<td>Rinçage</td>\r\n<td>Sert uniquement à rincer le linge, sans faire un lavage complet.</td>\r\n</tr>\r\n<tr>\r\n<td>Essorage + vidange</td>\r\n<td>Sert à essorer et vidanger l’eau. Utile si le linge est encore trop mouillé.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"warning-box\"><strong>Conseil :</strong> pour un lavage normal, utilisez le programme <strong>3 - Coton 40°</strong> ou <strong>5 - Synthétiques 40°</strong>. Ne surchargez pas la machine et utilisez peu de lessive.</div>\r\n<ol class=\"step-list\">\r\n<li>Mettez le linge dans le tambour sans trop le remplir.</li>\r\n<li>Mettez une petite quantité de lessive dans le compartiment <strong>2</strong>.</li>\r\n<li>Allumez la machine avec le bouton <strong>ON/OFF</strong>.</li>\r\n<li>Choisissez le programme avec la grande molette.</li>\r\n<li>Appuyez sur <strong>START/PAUSE</strong> pour démarrer.</li>\r\n</ol>\r\n<div class=\"warning-box\">À la fin du séjour, si possible, mettez les serviettes utilisées dans la machine <strong>sans la lancer</strong>.</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Comandi della lavatrice\" src=\"/assets/manuale-lavatrice-comandi.jpg\"/>\r\n</div>\r\n<h3>Hauptbedienelemente</h3>\r\n<div class=\"remote-guide\">\r\n<div class=\"remote-card remote-white\">\r\n<strong>ON/OFF-Taste</strong>\r\n<p>Sie dient zum Ein- und Ausschalten der Waschmaschine.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Programmwähler</strong>\r\n<p>Sie dient zur Auswahl des Waschprogramms. Dreht sie auf die gewünschte Nummer, gemäß der Programmtabelle.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Temperaturwähler</strong>\r\n<p>Sie dient zur Auswahl der Wassertemperatur: 20°, 30°, 40°, 50°, 60°, 70° oder 90°. Für eine normale Wäsche empfehlen wir 30° oder 40°.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Schleuderdrehzahlwähler</strong>\r\n<p>Sie dient zur Auswahl der Schleuderdrehzahl. Je höher die Zahl, desto trockener kommen die Wäschestücke heraus. Für eine normale Nutzung könnt ihr 700/800 Umdrehungen einstellen.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>START/PAUSE-Taste</strong>\r\n<p>Sie dient zum Starten des Waschvorgangs oder zum Pausieren.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>EcoTime-Taste</strong>\r\n<p>Sie kann verwendet werden, um bei leichteren Wäschen Zeit oder Verbrauch zu reduzieren. Sie ist nicht unbedingt erforderlich: wenn ihr unsicher seid, könnt ihr sie weglassen.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Energy Saver-Taste</strong>\r\n<p>Sie dient für eine verbrauchsärmere Wäsche. Sie kann die Waschzeit verlängern. Benutzt sie nur, wenn ihr sie braucht.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Extra-Spülen-Taste</strong>\r\n<p>Es ist die Taste mit dem Tropfensymbol. Sie fügt einen zusätzlichen Spülgang hinzu, nützlich, wenn ihr zu viel Waschmittel verwendet habt oder für empfindliche Wäsche.</p>\r\n</div>\r\n<div class=\"remote-card remote-white\">\r\n<strong>Startzeitvorwahl-Taste</strong>\r\n<p>Es ist die Taste mit dem Uhrsymbol. Sie dient dazu, die Waschmaschine nach 3, 6, 9 oder 12 Stunden starten zu lassen. Für eine normale Nutzung ist sie nicht nötig.</p>\r\n</div>\r\n</div>\r\n<p>Die Waschmaschine kann bei Bedarf benutzt werden. Wir bitten euch nur, sie nicht zu überladen und wenig Waschmittel zu verwenden.</p>\r\n<h3>Wo das Waschmittel hinkommt</h3>\r\n<div class=\"manual-img small\">\r\n<img alt=\"Cassetto detersivi della lavatrice\" src=\"/assets/manuale-lavatrice-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Fach 2:</strong> Waschmittel für den Hauptwaschgang. Es ist das, das in den meisten Fällen verwendet wird.</li>\r\n<li><strong>Fach mit der Blume:</strong> Weichspüler, nur wenn ihr ihn verwenden wollt.</li>\r\n<li><strong>Fach 1:</strong> Vorwäsche. Normalerweise nicht nötig.</li>\r\n</ul>\r\n<h3>Hauptprogramme</h3>\r\n<div class=\"manual-img wide\">\r\n<img alt=\"Programmi della lavatrice\" src=\"/assets/manuale-lavatrice-programmi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programm</th>\r\n<th>Wann verwenden</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1 - Baumwolle 90°</td>\r\n<td>Für sehr robuste und sehr schmutzige weiße Wäsche. Verwendet es selten.</td>\r\n</tr>\r\n<tr>\r\n<td>2 - Baumwolle 60°</td>\r\n<td>Für Handtücher, Bettwäsche und robuste Wäsche.</td>\r\n</tr>\r\n<tr>\r\n<td>3 - Baumwolle 40°</td>\r\n<td>Empfohlene Wahl für eine normale tägliche Wäsche.</td>\r\n</tr>\r\n<tr>\r\n<td>4 - Synthetik 60°</td>\r\n<td>Für robustere synthetische Kleidungsstücke.</td>\r\n</tr>\r\n<tr>\r\n<td>5 - Synthetik 40°</td>\r\n<td>Für normale synthetische Kleidungsstücke. Gute Wahl für nicht zu schmutzige Kleidung.</td>\r\n</tr>\r\n<tr>\r\n<td>6 / 7 / 8 - Zone 20°</td>\r\n<td>Für Wäsche bei niedriger Temperatur, leicht verschmutzte oder empfindlichere Kleidungsstücke.</td>\r\n</tr>\r\n<tr>\r\n<td>9 / 10 / 11 - Special</td>\r\n<td>Programme für besondere Kleidungsstücke. Verwendet sie nur, wenn ihr wisst, welches Programm ihr braucht.</td>\r\n</tr>\r\n<tr>\r\n<td>12 / 13 / 14 - Sport</td>\r\n<td>Für Sportbekleidung oder Schuhe, falls nötig.</td>\r\n</tr>\r\n<tr>\r\n<td>Rinse</td>\r\n<td>Dient nur zum Spülen der Wäsche, ohne einen vollständigen Waschgang durchzuführen.</td>\r\n</tr>\r\n<tr>\r\n<td>Spin + Drain</td>\r\n<td>Dient zum Schleudern und Ablassen des Wassers. Nützlich, wenn die Wäsche noch zu nass ist.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"warning-box\"><strong>Tipp:</strong> für eine normale Wäsche verwendet das Programm <strong>3 - Baumwolle 40°</strong> oder <strong>5 - Synthetik 40°</strong>. Überladet die Waschmaschine nicht und verwendet wenig Waschmittel.</div>\r\n<ol class=\"step-list\">\r\n<li>Gebt die Wäsche in die Trommel, ohne sie zu voll zu machen.</li>\r\n<li>Gebt wenig Waschmittel in das Fach <strong>2</strong>.</li>\r\n<li>Schaltet die Waschmaschine mit der <strong>ON/OFF</strong>-Taste ein.</li>\r\n<li>Wählt das Programm mit dem großen Drehregler.</li>\r\n<li>Drückt <strong>START/PAUSE</strong>, um zu starten.</li>\r\n</ol>\r\n<div class=\"warning-box\">Am Ende des Aufenthalts legt, wenn möglich, die gebrauchten Handtücher in die Waschmaschine, <strong>ohne sie zu starten</strong>.</div>\r\n</div>\r\n</details>"}},{"id":"manual-8","index":"009","icon":"ShowerHead","image":null,"tag":{"it":"Doccia","en":"Shower","es":"Ducha","fr":"Douche","de":"Dusche"},"title":{"it":"Doccino del bagno","en":"Bathroom shower sprayer","es":"Ducha de baño","fr":"Douchette de salle de bain","de":"Badezimmer-Brausebrause"},"body":{"it":"<div class=\"manual-content\">\r\n<p>Il doccino del bagno serve per lavare la tazza del gabinetto e per la pulizia veloce della doccia o del bidet. Ecco come si usa.</p>\r\n<h3>Come usare il doccino</h3>\r\n<ol class=\"step-list\">\r\n<li>Aprite la manopola dell’acqua del lavandino o della parete, in base a come è collegato il doccino.</li>\r\n<li>Premete il pulsante o la levetta del doccino: l’acqua esce dal getto.</li>\r\n<li>Dirigete il getto sulla superficie da pulire, poi richiudete l’acqua della manopola.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Attenzione:</strong> dopo l’uso chiudete sempre l’acqua e lasciate il doccino nella sua sede, così non lascia perdite.</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni doccino italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/doccinoitalianoinglese.png\"/>\r\n<img alt=\"Instrucciones ducha en español y francés\" class=\"moka-language-image\" data-langs=\"es,fr\" src=\"/assets/doccinofrancesespagnolo.png\"/>\r\n<img alt=\"Brause-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/doccinotedesco.png\"/>\r\n</div>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<p>The bathroom sprayer is used to clean the toilet bowl and for quick cleaning of the shower or the bidet. Here is how to use it.</p>\r\n<h3>How to use the sprayer</h3>\r\n<ol class=\"step-list\">\r\n<li>Open the water tap on the sink or the wall, depending on how the sprayer is connected.</li>\r\n<li>Press the sprayer button or lever: water comes out of the nozzle.</li>\r\n<li>Point the jet at the surface you want to clean, then close the water tap.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Attention:</strong> after use always turn off the water and put the sprayer back in its holder, so it does not leak.</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni doccino italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/doccinoitalianoinglese.png\"/>\r\n<img alt=\"Instrucciones ducha en español y francés\" class=\"moka-language-image\" data-langs=\"es,fr\" src=\"/assets/doccinofrancesespagnolo.png\"/>\r\n<img alt=\"Brause-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/doccinotedesco.png\"/>\r\n</div>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<p>La ducha del baño sirve para lavar la taza del inodoro y para la limpieza rápida de la ducha o del bidé. Así se usa.</p>\r\n<h3>Cómo usar la ducha</h3>\r\n<ol class=\"step-list\">\r\n<li>Abrid la llave del agua del lavabo o de la pared, según cómo esté conectada la ducha.</li>\r\n<li>Pulsad el botón o la palanca de la ducha: el agua sale por el chorro.</li>\r\n<li>Dirigid el chorro hacia la superficie a limpiar y luego cerrad la llave del agua.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Atención:</strong> después del uso cerrad siempre el agua y dejad la ducha en su soporte, para que no gotee.</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni doccino italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/doccinoitalianoinglese.png\"/>\r\n<img alt=\"Instrucciones ducha en español y francés\" class=\"moka-language-image\" data-langs=\"es,fr\" src=\"/assets/doccinofrancesespagnolo.png\"/>\r\n<img alt=\"Brause-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/doccinotedesco.png\"/>\r\n</div>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<p>La douchette de salle de bain sert à laver la cuvette des toilettes et au nettoyage rapide de la douche ou du bidet. Voici comment l’utiliser.</p>\r\n<h3>Comment utiliser la douchette</h3>\r\n<ol class=\"step-list\">\r\n<li>Ouvrez le robinet d’eau du lavabo ou du mur, selon la façon dont la douchette est raccordée.</li>\r\n<li>Appuyez sur le bouton ou la gâchette de la douchette : l’eau sort par le jet.</li>\r\n<li>Dirigez le jet vers la surface à nettoyer, puis refermez le robinet d’eau.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Attention :</strong> après usage, fermez toujours l’eau et remettez la douchette en place, pour éviter les fuites.</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni doccino italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/doccinoitalianoinglese.png\"/>\r\n<img alt=\"Instrucciones ducha en español y francés\" class=\"moka-language-image\" data-langs=\"es,fr\" src=\"/assets/doccinofrancesespagnolo.png\"/>\r\n<img alt=\"Brause-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/doccinotedesco.png\"/>\r\n</div>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<p>Die Badezimmer-Brause dient zum Reinigen der Toilettenschüssel und für die schnelle Reinigung der Dusche oder des Bidets. So wird sie benutzt.</p>\r\n<h3>So benutzt ihr die Brause</h3>\r\n<ol class=\"step-list\">\r\n<li>Öffnet das Wasser am Waschbecken oder an der Wand, je nachdem, wie die Brause angeschlossen ist.</li>\r\n<li>Drückt den Knopf oder den Hebel der Brause: Das Wasser kommt aus dem Strahl.</li>\r\n<li>Richtet den Strahl auf die zu reinigende Fläche und schließt dann das Wasser am Hahn.</li>\r\n</ol>\r\n<div class=\"warning-box\"><strong>Achtung:</strong> Nach dem Gebrauch immer das Wasser schließen und die Brause zurück in ihre Halterung hängen, damit nichts tropft.</div>\r\n<div aria-live=\"polite\" class=\"moka-language-images\">\r\n<img alt=\"Istruzioni doccino italiano e inglese\" class=\"moka-language-image\" data-langs=\"it,en\" src=\"/assets/doccinoitalianoinglese.png\"/>\r\n<img alt=\"Instrucciones ducha en español y francés\" class=\"moka-language-image\" data-langs=\"es,fr\" src=\"/assets/doccinofrancesespagnolo.png\"/>\r\n<img alt=\"Brause-Anleitung auf Deutsch\" class=\"moka-language-image\" data-langs=\"de\" src=\"/assets/doccinotedesco.png\"/>\r\n</div>\r\n</div>\r\n</details>"}},{"id":"manual-9","index":"010","icon":"UtensilsCrossed","image":"assets/manuale-lavastoviglie-cassetto.jpg","tag":{"it":"Lavastoviglie","en":"Dishwasher","es":"Lavavajillas","fr":"Lave-vaisselle","de":"Geschirrspüler"},"title":{"it":"Lavastoviglie","en":"Dishwasher","es":"Lavavajillas","fr":"Lave-vaisselle","de":"Geschirrspüler"},"body":{"it":"<div class=\"manual-content\">\r\n<p>La lavastoviglie può essere usata normalmente. Vi chiediamo solo di non inserire oggetti non adatti. Non usate capsule: bisogna usare solo sapone liquido per lavastoviglie.</p>\r\n<h3>Dove mettere detersivo e brillantante</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Vaschetta detersivo e brillantante lavastoviglie\" src=\"/assets/manuale-lavastoviglie-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Detersivo:</strong> usate solo sapone liquido specifico per lavastoviglie e inseritelo nello sportellino principale. Le capsule e le pastiglie non sono ammesse.</li>\r\n<li><strong>Brillantante:</strong> va inserito nel serbatoio con il simbolo della stellina. Non va riempito ogni volta, solo quando è vuoto.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Non usate mai detersivo per piatti a mano</strong> nella lavastoviglie: fa troppa schiuma e può causare perdite o danni.</div>\r\n<h3>Come avviare la lavastoviglie</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Comandi della lavastoviglie\" src=\"/assets/manuale-lavastoviglie-comandi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programma</th>\r\n<th>Quando usarlo</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Eco 50°</td>\r\n<td>Programma consigliato per piatti normalmente sporchi. Consuma meno.</td>\r\n</tr>\r\n<tr>\r\n<td>Normale 65°</td>\r\n<td>Per piatti e pentole più sporchi.</td>\r\n</tr>\r\n<tr>\r\n<td>Intensivo 70°</td>\r\n<td>Solo per sporco molto resistente.</td>\r\n</tr>\r\n<tr>\r\n<td>Ammollo</td>\r\n<td>Per risciacquare velocemente prima di un lavaggio completo.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<ol class=\"step-list\">\r\n<li>Caricate la lavastoviglie senza bloccare i bracci interni.</li>\r\n<li>Inserite il detersivo nello sportellino principale e chiudetelo.</li>\r\n<li>Premete il tasto di accensione.</li>\r\n<li>Selezionate il programma desiderato, di solito <strong>Eco 50°</strong> o <strong>Normale 65°</strong>.</li>\r\n<li>Chiudete bene lo sportello e lasciate terminare il ciclo.</li>\r\n</ol>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<p>The dishwasher can be used normally. Please do not put unsuitable items inside. Do not use tablets or pods: use only liquid dishwasher detergent.</p>\r\n<h3>Where to put detergent and rinse aid</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Vaschetta detersivo e brillantante lavastoviglie\" src=\"/assets/manuale-lavastoviglie-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Detergent:</strong> use only liquid dishwasher detergent and put it in the main dispenser. Tablets and pods are not allowed.</li>\r\n<li><strong>Rinse aid:</strong> put it in the container with the star symbol. It does not need to be filled every time, only when empty.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Never use hand dishwashing liquid</strong> in the dishwasher: it creates too much foam and may cause leaks or damage.</div>\r\n<h3>How to start the dishwasher</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Comandi della lavastoviglie\" src=\"/assets/manuale-lavastoviglie-comandi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programme</th>\r\n<th>When to use it</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Eco 50°</td>\r\n<td>Recommended programme for normally dirty dishes. It uses less energy.</td>\r\n</tr>\r\n<tr>\r\n<td>Normal 65°</td>\r\n<td>For dirtier dishes and pans.</td>\r\n</tr>\r\n<tr>\r\n<td>Intensive 70°</td>\r\n<td>Only for very stubborn dirt.</td>\r\n</tr>\r\n<tr>\r\n<td>Soak</td>\r\n<td>To quickly rinse before a full wash.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<ol class=\"step-list\">\r\n<li>Load the dishwasher without blocking the internal spray arms.</li>\r\n<li>Put the detergent in the main dispenser and close it.</li>\r\n<li>Press the power button.</li>\r\n<li>Select the desired programme, usually <strong>Eco 50°</strong> or <strong>Normal 65°</strong>.</li>\r\n<li>Close the door properly and let the cycle finish.</li>\r\n</ol>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<p>El lavavajillas puede usarse normalmente. No metáis objetos no aptos. No uséis cápsulas: hay que usar solo detergente líquido para lavavajillas.</p>\r\n<h3>Dónde poner detergente y abrillantador</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Vaschetta detersivo e brillantante lavastoviglie\" src=\"/assets/manuale-lavastoviglie-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Detergente:</strong> usad solo detergente líquido específico para lavavajillas y ponedlo en el compartimento principal. No se permiten cápsulas ni pastillas.</li>\r\n<li><strong>Abrillantador:</strong> se pone en el depósito con el símbolo de la estrella. No hay que llenarlo cada vez, solo cuando esté vacío.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>No uséis nunca detergente para lavar platos a mano</strong> en el lavavajillas: hace demasiada espuma y puede causar fugas o daños.</div>\r\n<h3>Cómo iniciar el lavavajillas</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Comandi della lavastoviglie\" src=\"/assets/manuale-lavastoviglie-comandi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programa</th>\r\n<th>Cuándo usarlo</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Eco 50°</td>\r\n<td>Programa recomendado para platos normalmente sucios. Consume menos.</td>\r\n</tr>\r\n<tr>\r\n<td>Normal 65°</td>\r\n<td>Para platos y ollas más sucios.</td>\r\n</tr>\r\n<tr>\r\n<td>Intensivo 70°</td>\r\n<td>Solo para suciedad muy resistente.</td>\r\n</tr>\r\n<tr>\r\n<td>Remojo</td>\r\n<td>Para aclarar rápidamente antes de un lavado completo.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<ol class=\"step-list\">\r\n<li>Cargad el lavavajillas sin bloquear los brazos internos.</li>\r\n<li>Poned el detergente en el compartimento principal y cerradlo.</li>\r\n<li>Pulsad el botón de encendido.</li>\r\n<li>Seleccionad el programa deseado, normalmente <strong>Eco 50°</strong> o <strong>Normal 65°</strong>.</li>\r\n<li>Cerrad bien la puerta y dejad que termine el ciclo.</li>\r\n</ol>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<p>Le lave-vaisselle peut être utilisé normalement. Ne mettez pas d’objets non adaptés. N’utilisez pas de capsules : utilisez uniquement du liquide vaisselle spécial lave-vaisselle.</p>\r\n<h3>Où mettre le détergent et le liquide de rinçage</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Vaschetta detersivo e brillantante lavastoviglie\" src=\"/assets/manuale-lavastoviglie-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Détergent :</strong> utilisez uniquement du liquide vaisselle spécial lave-vaisselle et mettez-le dans le compartiment principal. Les capsules et les tablettes sont interdites.</li>\r\n<li><strong>Liquide de rinçage :</strong> mettez-le dans le réservoir avec le symbole étoile. Il ne faut pas le remplir à chaque fois, seulement lorsqu’il est vide.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>N’utilisez jamais de liquide vaisselle à main</strong> dans le lave-vaisselle : il mousse trop et peut provoquer des fuites ou des dégâts.</div>\r\n<h3>Comment lancer le lave-vaisselle</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Comandi della lavastoviglie\" src=\"/assets/manuale-lavastoviglie-comandi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programme</th>\r\n<th>Quand l’utiliser</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Éco 50°</td>\r\n<td>Programme conseillé pour la vaisselle normalement sale. Il consomme moins.</td>\r\n</tr>\r\n<tr>\r\n<td>Normal 65°</td>\r\n<td>Pour la vaisselle et les casseroles plus sales.</td>\r\n</tr>\r\n<tr>\r\n<td>Intensif 70°</td>\r\n<td>Seulement pour la saleté très incrustée.</td>\r\n</tr>\r\n<tr>\r\n<td>Trempage</td>\r\n<td>Pour rincer rapidement avant un lavage complet.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<ol class=\"step-list\">\r\n<li>Chargez le lave-vaisselle sans bloquer les bras internes.</li>\r\n<li>Mettez le détergent dans le compartiment principal et fermez-le.</li>\r\n<li>Appuyez sur le bouton d’allumage.</li>\r\n<li>Sélectionnez le programme souhaité, généralement <strong>Éco 50°</strong> ou <strong>Normal 65°</strong>.</li>\r\n<li>Fermez bien la porte et laissez le cycle se terminer.</li>\r\n</ol>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<p>Der Geschirrspüler kann normal benutzt werden. Legt keine ungeeigneten Gegenstände hinein. Verwendet keine Tabs oder Kapseln: Es darf nur flüssiger Geschirrspülreiniger verwendet werden.</p>\r\n<h3>Wo Reinigungsmittel und Klarspüler hinkommen</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Vaschetta detersivo e brillantante lavastoviglie\" src=\"/assets/manuale-lavastoviglie-cassetto.jpg\"/>\r\n</div>\r\n<ul class=\"simple-list\">\r\n<li><strong>Reinigungsmittel:</strong> Verwendet nur flüssigen Geschirrspülreiniger und gebt ihn in das Hauptfach. Tabs und Kapseln sind nicht erlaubt.</li>\r\n<li><strong>Klarspüler:</strong> wird in den Behälter mit dem Sternsymbol gefüllt. Er muss nicht jedes Mal nachgefüllt werden, nur wenn er leer ist.</li>\r\n</ul>\r\n<div class=\"warning-box\"><strong>Verwendet niemals Spülmittel für Handwäsche</strong> im Geschirrspüler: Es schäumt zu stark und kann Lecks oder Schäden verursachen.</div>\r\n<h3>So startet ihr den Geschirrspüler</h3>\r\n<div class=\"manual-img\">\r\n<img alt=\"Comandi della lavastoviglie\" src=\"/assets/manuale-lavastoviglie-comandi.jpg\"/>\r\n</div>\r\n<table class=\"program-table\">\r\n<thead>\r\n<tr>\r\n<th>Programm</th>\r\n<th>Wann verwenden</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Eco 50°</td>\r\n<td>Empfohlenes Programm für normal verschmutztes Geschirr. Verbraucht weniger.</td>\r\n</tr>\r\n<tr>\r\n<td>Normal 65°</td>\r\n<td>Für stärker verschmutztes Geschirr und Töpfe.</td>\r\n</tr>\r\n<tr>\r\n<td>Intensiv 70°</td>\r\n<td>Nur für sehr hartnäckige Verschmutzung.</td>\r\n</tr>\r\n<tr>\r\n<td>Einweichen</td>\r\n<td>Zum schnellen Spülen vor einem vollständigen Waschgang.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<ol class=\"step-list\">\r\n<li>Beladet den Geschirrspüler, ohne die inneren Sprüharme zu blockieren.</li>\r\n<li>Gebt das Reinigungsmittel in das Hauptfach und schließt es.</li>\r\n<li>Drückt die Einschalttaste.</li>\r\n<li>Wählt das gewünschte Programm, normalerweise <strong>Eco 50°</strong> oder <strong>Normal 65°</strong>.</li>\r\n<li>Schließt die Tür gut und lasst den Zyklus zu Ende laufen.</li>\r\n</ol>\r\n</div>\r\n</details>"}},{"id":"manual-10","index":"011","icon":"LifeBuoy","image":null,"tag":{"it":"Aiuto","en":"Help","es":"Ayuda","fr":"Aide","de":"Hilfe"},"title":{"it":"Problemi durante il soggiorno","en":"Problems during your stay","es":"Problemas durante la estancia","fr":"Problèmes pendant le séjour","de":"Probleme während des Aufenthalts"},"body":{"it":"<div class=\"manual-content\">\r\n<p>Se qualcosa non funziona o avete un dubbio, vi chiediamo di avvisarci subito. Faremo il possibile per aiutarvi rapidamente.</p>\r\n<ul class=\"simple-list\">\r\n<li><strong>Problemi urgenti:</strong> chiamateci.</li>\r\n<li><strong>Richieste non urgenti:</strong> scriveteci su WhatsApp.</li>\r\n<li><strong>Emergenze:</strong> chiamate il 112 o il 118 se necessario.</li>\r\n</ul>\r\n</div>\r\n</details>","en":"<div class=\"manual-content\">\r\n<p>If something does not work or you have a doubt, please let us know immediately. We will do our best to help you quickly.</p>\r\n<ul class=\"simple-list\">\r\n<li><strong>Urgent problems:</strong> call us.</li>\r\n<li><strong>Non-urgent requests:</strong> message us on WhatsApp.</li>\r\n<li><strong>Emergencies:</strong> call 112 or 118 if needed.</li>\r\n</ul>\r\n</div>\r\n</details>","es":"<div class=\"manual-content\">\r\n<p>Si algo no funciona o tenéis alguna duda, os pedimos que nos aviséis enseguida. Haremos todo lo posible para ayudaros rápidamente.</p>\r\n<ul class=\"simple-list\">\r\n<li><strong>Problemas urgentes:</strong> llamadnos.</li>\r\n<li><strong>Solicitudes no urgentes:</strong> escribidnos por WhatsApp.</li>\r\n<li><strong>Emergencias:</strong> llamad al 112 o al 118 si es necesario.</li>\r\n</ul>\r\n</div>\r\n</details>","fr":"<div class=\"manual-content\">\r\n<p>Si quelque chose ne fonctionne pas ou si vous avez un doute, merci de nous prévenir immédiatement. Nous ferons de notre mieux pour vous aider rapidement.</p>\r\n<ul class=\"simple-list\">\r\n<li><strong>Problèmes urgents :</strong> appelez-nous.</li>\r\n<li><strong>Demandes non urgentes :</strong> écrivez-nous sur WhatsApp.</li>\r\n<li><strong>Urgences :</strong> appelez le 112 ou le 118 si nécessaire.</li>\r\n</ul>\r\n</div>\r\n</details>","de":"<div class=\"manual-content\">\r\n<p>Wenn etwas nicht funktioniert oder ihr eine Frage habt, bitten wir euch, uns sofort zu benachrichtigen. Wir werden unser Bestes tun, um euch schnell zu helfen.</p>\r\n<ul class=\"simple-list\">\r\n<li><strong>Dringende Probleme:</strong> ruft uns an.</li>\r\n<li><strong>Nicht dringende Anfragen:</strong> schreibt uns auf WhatsApp.</li>\r\n<li><strong>Notfälle:</strong> ruft bei Bedarf 112 oder 118 an.</li>\r\n</ul>\r\n</div>\r\n</details>"}}];
